const BIOGRAFIAS = {"homero":{"name":"Homero","dates":"s. VIII a. C.","born":-750,"died":-700,"place":"","role":"poeta épico griego","idea":"Sus poemas épicos fijaron la imagen griega de los dioses y los héroes, y fueron la base de la educación y del pensamiento mítico anterior a la filosofía.","obras":["Ilíada","Odisea"],"fuente":"Vida de Homero atribuida a Heródoto; Certamen de Homero y Hesíodo; Heráclito, fragmento sobre Homero y los piojos","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-mito","hf-kant-poetas"]},"hesiodo":{"name":"Hesíodo","dates":"fl. c. 700 a. C.","born":-740,"died":-670,"place":"Ascra (Beocia)","role":"poeta griego","idea":"Narró el origen del mundo y de los dioses como una genealogía que parte del Caos, el gran modelo de explicación mítica frente al que nacerá la filosofía.","obras":["Teogonía","Los trabajos y los días"],"fuente":"Hesíodo, Los trabajos y los días; Certamen de Homero y Hesíodo","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-mito"]},"solon":{"name":"Solón","dates":"c. 640 – c. 560 a. C.","born":-640,"died":-560,"place":"Atenas","role":"legislador y poeta ateniense","idea":"Con sus reformas canceló las deudas, prohibió la esclavitud por deudas y repartió los derechos políticos según la riqueza, preparando el camino de la democracia ateniense.","obras":["Elegías (fragmentos)"],"fuente":"Heródoto, Historias I","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-mito","hf-sofistas"]},"tales":{"name":"Tales de Mileto","dates":"c. 624 – c. 546 a. C.","born":-624,"died":-546,"place":"Mileto (Jonia, actual Turquía)","role":"filósofo presocrático","idea":"Considerado el primer filósofo, buscó un principio natural común a todas las cosas, el arjé, y afirmó que ese principio es el agua.","obras":[],"fuente":"Aristóteles, Política I","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-mito","hf-preso"]},"anaximandro":{"name":"Anaximandro","dates":"c. 610 – c. 546 a. C.","born":-610,"died":-546,"place":"Mileto (Jonia, actual Turquía)","role":"filósofo presocrático","idea":"El principio de todas las cosas no es ningún elemento concreto, sino el ápeiron, algo ilimitado e indeterminado del que surgen y al que vuelven los contrarios.","obras":[],"fuente":"Cicerón, Sobre la adivinación I","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-mito","hf-preso","hf-kant-juicios"]},"anaximenes":{"name":"Anaxímenes","dates":"c. 586 – c. 528 a. C.","born":-586,"died":-528,"place":"Mileto (Jonia, actual Turquía)","role":"filósofo presocrático","idea":"El principio de todo es el aire, que por rarefacción se hace fuego y por condensación se convierte en viento, nubes, agua, tierra y piedra.","obras":[],"block":"ant","subjects":["hf"],"temas":["hf-preso"]},"pitagoras":{"name":"Pitágoras de Samos","dates":"c. 570 – c. 495 a. C.","born":-570,"died":-495,"place":"Samos (Grecia)","role":"filósofo y matemático presocrático","idea":"La esencia de la realidad es el número: el universo es un orden armónico y matemático, y el alma inmortal debe purificarse a lo largo de sucesivas reencarnaciones.","obras":[],"fuente":"Jenófanes, fragmento citado por Diógenes Laercio, Vidas VIII","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-preso","hf-renacimiento-magia"]},"jenofanes":{"name":"Jenófanes de Colofón","dates":"c. 570 – c. 475 a. C.","born":-570,"died":-475,"place":"Colofón (Jonia, actual Turquía)","role":"poeta y filósofo presocrático","idea":"Cada pueblo imagina a los dioses a su imagen; frente a ese antropomorfismo, propuso un dios único que no se parece a los mortales ni en figura ni en pensamiento.","obras":["Elegías (fragmentos)","Silos (fragmentos)"],"fuente":"Aristóteles, Retórica II","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-mito","hf-preso"]},"lao_zi":{"name":"Lao Zi","dates":"s. VI-IV a. C. (según la tradición)","born":-570,"died":-480,"place":"Estado de Chu (China)","role":"sabio chino, al que se atribuye el Daodejing","idea":"El Dao, el camino de la naturaleza, actúa sin forzar: el sabio sigue ese ejemplo, prefiere lo humilde y lo flexible, y gobierna interviniendo lo menos posible (wu wei).","obras":["Daodejing o Tao Te Ching (atribuido)"],"fuente":"Sima Qian, Memorias históricas, cap. 63 (s. I a. C.)","tradicion":true,"block":"ant","subjects":["hf"],"temas":[]},"confucio":{"name":"Confucio","dates":"551 – 479 a. C.","born":-551,"died":-479,"place":"Estado de Lu (actual Qufu, China)","role":"maestro y pensador moral chino","idea":"Una buena sociedad nace de personas bien formadas: la humanidad (ren), el respeto a los ritos (li) y el ejemplo de quien gobierna valen más que el castigo.","obras":["Analectas (Lunyu), recopiladas por sus discípulos"],"fuente":"Analectas II, 4","tradicion":false,"block":"ant","subjects":["hf"],"temas":[]},"heraclito":{"name":"Heráclito de Éfeso","dates":"c. 540 – c. 480 a. C.","born":-540,"died":-480,"place":"Éfeso (Jonia, actual Turquía)","role":"filósofo presocrático","idea":"Todo fluye y nada permanece: la realidad es un cambio incesante, nacido de la lucha de contrarios pero regido por un logos o ley racional común.","obras":["Sobre la naturaleza (fragmentos)"],"fuente":"Aristóteles, Partes de los animales I","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-mito","hf-preso","hf-ap","hf-platon","hf-kant-juicios"]},"parmenides":{"name":"Parménides de Elea","dates":"c. 515 – c. 450 a. C.","born":-515,"died":-450,"place":"Elea (Magna Grecia, actual Italia)","role":"filósofo presocrático","idea":"El ser es y el no ser no es: lo real es único, eterno e inmóvil, y el cambio que muestran los sentidos es solo apariencia.","obras":["Sobre la naturaleza (poema, fragmentos)"],"fuente":"Plutarco, Contra Colotes; Estrabón, Geografía VI; Diógenes Laercio, Vidas IX","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-mito","hf-preso","hf-ap","hf-platon","hf-montaigne-ensayos","hf-kant-juicios"]},"anaxagoras":{"name":"Anaxágoras de Clazómenas","dates":"c. 500 – 428 a. C.","born":-500,"died":-428,"place":"Clazómenas (Jonia, actual Turquía)","role":"filósofo presocrático","idea":"Todo está formado por infinitas semillas mezcladas, y una inteligencia, el Nous, puso en marcha el torbellino que separó y ordenó el cosmos.","obras":["Sobre la naturaleza (fragmentos)"],"fuente":"Diógenes Laercio, Vidas II; Aristóteles, Ética eudemia I","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-preso"]},"empedocles":{"name":"Empédocles de Agrigento","dates":"c. 495 – c. 435 a. C.","born":-495,"died":-435,"place":"Agrigento (Sicilia)","role":"filósofo presocrático","idea":"Todo se compone de cuatro raíces eternas, tierra, agua, aire y fuego, que el Amor une y el Odio separa en un ciclo cósmico sin fin.","obras":["Sobre la naturaleza (fragmentos)","Purificaciones (fragmentos)"],"fuente":"Diógenes Laercio, Vidas VIII","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-preso"]},"zenon_elea":{"name":"Zenón de Elea","dates":"c. 490 – c. 430 a. C.","born":-490,"died":-430,"place":"Elea (Magna Grecia)","role":"filósofo eleata","idea":"Si se admite que hay muchas cosas y que hay movimiento, se cae en contradicciones; por eso tiene razón Parménides: el ser es uno e inmóvil.","obras":[],"block":"ant","subjects":["hf"],"temas":[]},"protagoras":{"name":"Protágoras de Abdera","dates":"c. 485 – c. 411 a. C.","born":-485,"died":-411,"place":"Abdera (Tracia, actual Grecia)","role":"sofista griego","idea":"El ser humano es la medida de todas las cosas: no hay verdades ni valores absolutos, sino lo que a cada persona o comunidad le parece verdadero o justo.","obras":["Sobre los dioses (fragmentos)","La verdad (fragmentos)"],"fuente":"Aulo Gelio, Noches áticas V; Diógenes Laercio, Vidas IX","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-beefs","hf-sofistas","hf-etica","hf-kant-juicios"]},"gorgias":{"name":"Gorgias de Leontinos","dates":"c. 485 – c. 380 a. C.","born":-485,"died":-380,"place":"Leontinos (Sicilia)","role":"sofista y maestro de retórica","idea":"Nada existe, y si existiera no podría conocerse ni comunicarse; por eso el lenguaje no expresa lo que son las cosas, sino que es un poderoso instrumento de persuasión.","obras":["Sobre el no ser (resúmenes)","Encomio de Helena","Defensa de Palamedes"],"fuente":"Filóstrato, Vidas de los sofistas I; Platón, Gorgias; Pausanias, Descripción de Grecia X","tradicion":false,"block":"ant","subjects":["hf"],"temas":["hf-beefs","hf-sofistas","hf-platon-superficie","hf-etica"]},"meliso":{"name":"Meliso de Samos","dates":"fl. c. 440 a. C.","born":-480,"died":null,"place":"Samos (mar Egeo)","role":"filósofo eleata y almirante","idea":"El ser es uno, eterno e infinito; como no existe el vacío, nada puede moverse.","obras":["Sobre la naturaleza o sobre el ser"],"block":"ant","subjects":["hf"],"temas":[]},"leucipo":{"name":"Leucipo","dates":"fl. c. 440 a. C.","born":-480,"died":null,"place":"Mileto o Abdera (no se sabe con seguridad)","role":"filósofo atomista","idea":"Todo está hecho de átomos indivisibles que se mueven en el vacío, y nada sucede al azar: todo ocurre por una razón y por necesidad.","obras":["La gran cosmología (atribuida)","Sobre el intelecto"],"block":"ant","subjects":["hf"],"temas":["hf-preso","hf-kant-juicios"]},"buda":{"name":"Siddhartha Gautama, el Buda","dates":"s. V a. C. (fechas inciertas)","born":-480,"died":-400,"place":"Lumbini (actual Nepal)","role":"maestro espiritual indio, fundador del budismo","idea":"La vida está atravesada por el sufrimiento, que nace del deseo y del apego; ese sufrimiento puede apagarse siguiendo un camino de vida recto y medido.","obras":["No escribió nada: sus enseñanzas se recogen en el Canon pali (Tripitaka) y en el Dhammapada"],"fuente":"Asvaghosa, Vida de Buda (Buddhacarita, s. I-II d. C.)","tradicion":true,"block":"ant","subjects":["hf"],"temas":[]},"filolao":{"name":"Filolao de Crotona","dates":"c. 470 – c. 385 a. C.","born":-470,"died":-385,"place":"Crotona (Magna Grecia)","role":"filósofo pitagórico","idea":"Todo lo que se conoce tiene número; el cosmos está hecho de lo ilimitado y de lo que pone límites, unidos por la armonía.","obras":[],"block":"ant","subjects":["hf"],"temas":[]},"trasimaco":{"name":"Trasímaco de Calcedonia","dates":"fl. c. 430 – 400 a. C.","born":-470,"died":null,"place":"Calcedonia (junto al Bósforo)","role":"sofista y maestro de retórica","idea":"La justicia no es otra cosa que lo que conviene al más fuerte: quien gobierna hace las leyes a su favor y llama «justo» a obedecerlas.","obras":[],"block":"ant","subjects":["hf"],"temas":["hf-beefs"]},"socrates":{"name":"Sócrates","dates":"470/469 – 399 a. C.","born":-470,"died":-399,"place":"Atenas","role":"filósofo griego","idea":"Quien conoce de verdad el bien obra bien; por eso la tarea filosófica es examinar la propia vida y buscar, dialogando, definiciones universales.","obras":[],"fuente":"Platón, Apología de Sócrates; Jenofonte, Apología","tradicion":false,"block":"ant","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-metodos","hf-beefs","hf-sofistas","hf-ap","hf-aa","hf-platon","hf-platon-superficie","hf-antropologia","hf-etica","hf-politica","hf-aristoteles-arabe","hf-montaigne-ensayos","hf-kant-poetas","hf-kant-juicios","hf-etica-deber","hf-sospecha","hf-filosofas-dialogo"]},"aspasia":{"name":"Aspasia de Mileto","dates":"c. 470 – c. 400 a. C.","born":-470,"died":-400,"place":"Mileto (Jonia, actual Turquía)","role":"oradora y maestra de retórica","idea":"Una mujer podía dominar la palabra y el pensamiento político tanto como los varones, y enseñar retórica a los ciudadanos más influyentes de Atenas.","obras":[],"fuente":"Esquines de Esfeto, Aspasia (fragmento transmitido por Cicerón, Sobre la invención retórica I)","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-sofistas","hf-filosofas-dialogo"]},"democrito":{"name":"Demócrito de Abdera","dates":"c. 460 – c. 370 a. C.","born":-460,"died":-370,"place":"Abdera (Tracia)","role":"filósofo presocrático atomista","idea":"Todo lo que existe está formado por átomos indivisibles que se mueven en el vacío; sus choques y combinaciones explican todos los cambios de la naturaleza.","obras":[],"fuente":"Séneca, Sobre la ira II; Cartas pseudohipocráticas","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-preso","hf-sofistas","hf-helenismo","hf-kant-juicios"]},"hipias":{"name":"Hipias de Élide","dates":"c. 460 – c. 400 a. C.","born":-460,"died":-400,"place":"Élide (Peloponeso)","role":"sofista griego","idea":"Las leyes de cada ciudad son convenciones humanas, variables y cambiables, distintas de las leyes naturales, que son universales y valen igual para todos.","obras":[],"fuente":"Platón, Hipias menor","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-sofistas"]},"antistenes":{"name":"Antístenes","dates":"c. 445 – c. 365 a. C.","born":-445,"died":-365,"place":"Atenas","role":"filósofo socrático","idea":"La virtud basta para ser feliz; para alcanzarla hay que llevar una vida austera, dominar los placeres y no depender de riquezas ni honores.","obras":[],"fuente":"Diógenes Laercio, Vidas VI","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-helenismo"]},"aristipo":{"name":"Aristipo de Cirene","dates":"c. 435 – c. 356 a. C.","born":-435,"died":-356,"place":"Cirene (actual Libia)","role":"filósofo socrático hedonista","idea":"El placer es el único bien y el fin de la vida; hay que disfrutar el placer presente sin dejarse dominar por él.","obras":[],"fuente":"Vitruvio, De architectura VI (prefacio)","tradicion":true,"block":"ant","subjects":["hf"],"temas":[]},"arquitas":{"name":"Arquitas de Tarento","dates":"c. 430 – c. 350 a. C.","born":-430,"died":-350,"place":"Tarento (Magna Grecia)","role":"filósofo pitagórico, matemático y político","idea":"El cálculo bien hecho pone fin a las disputas: cuando se conoce la proporción justa, ricos y pobres pueden ponerse de acuerdo.","obras":[],"block":"ant","subjects":["hf"],"temas":[]},"platon":{"name":"Platón","dates":"c. 427 – 347 a. C.","born":-427,"died":-347,"place":"Atenas","role":"filósofo griego","idea":"La realidad verdadera son las Ideas, eternas e inmutables, que solo capta la razón; el mundo sensible que percibimos es solo su copia imperfecta.","obras":["República","Fedón","Banquete","Fedro"],"fuente":"Diógenes Laercio, Vidas III","tradicion":true,"vida":[{"a":-399,"t":"Juicio y muerte de Sócrates, su maestro"},{"a":-388,"b":-361,"t":"Viajes a Sicilia (Siracusa)"},{"a":-387,"t":"Funda la Academia en Atenas"},{"a":-380,"b":-370,"t":"Escribe la República"}],"block":"ant","subjects":["hf"],"temas":["hf-historicidad","hf-comunidades-perseguidos","hf-euskal-herria","hf-metodos","hf-beefs","hf-mito","hf-preso","hf-sofistas","hf-ap","hf-aa","hf-platon","hf-platon-superficie","hf-platon-prejuicio","hf-antropologia","hf-etica","hf-politica","hf-helenismo","hf-medieval","hf-platon-agustin","hf-fe-razon","hf-aristoteles-arabe","hf-verdad-no-contradice","hf-islam-ideas","hf-toledo-traductores","hf-cinco-vias","hf-modernidad","hf-montaigne-ensayos","hf-renacimiento-magia","hf-utopias-autoras","hf-racionalismo","hf-kant-poetas","hf-kant-juicios","hf-sospecha","hf-filosofas-dialogo","hf-descartes-makro"]},"diogenes":{"name":"Diógenes de Sinope","dates":"c. 412 – 323 a. C.","born":-412,"died":-323,"place":"Sinope (actual Turquía)","role":"filósofo cínico","idea":"Para ser libre y feliz hay que necesitar lo mínimo, vivir conforme a la naturaleza y despreciar las convenciones sociales, la riqueza y el poder.","obras":[],"fuente":"Diógenes Laercio, Vidas VI","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-beefs","hf-preso","hf-helenismo"]},"espeusipo":{"name":"Espeusipo","dates":"c. 407 – 339 a. C.","born":-407,"died":-339,"place":"Atenas","role":"filósofo platónico, segundo director de la Academia","idea":"Los primeros principios de la realidad no son las Ideas, sino los números y las realidades matemáticas.","obras":[],"block":"ant","subjects":["hf"],"temas":[]},"aristoteles":{"name":"Aristóteles","dates":"384 – 322 a. C.","born":-384,"died":-322,"place":"Estagira (Macedonia)","role":"filósofo y científico griego","idea":"La realidad está en las sustancias concretas, compuestas de materia y forma; la felicidad consiste en realizar nuestra naturaleza racional mediante la virtud y la vida en comunidad.","obras":["Metafísica","Ética a Nicómaco","Política","Acerca del alma"],"fuente":"Eliano, Historias curiosas III; biografías antiguas de Aristóteles","tradicion":true,"vida":[{"a":-367,"b":-347,"t":"Alumno en la Academia de Platón"},{"a":-343,"b":-340,"t":"Educa a Alejandro Magno"},{"a":-335,"t":"Funda el Liceo en Atenas"},{"a":-323,"t":"Huye de Atenas"}],"block":"ant","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-filosofia-espanola","hf-metodos","hf-beefs","hf-mito","hf-preso","hf-sofistas","hf-aa","hf-platon","hf-antropologia","hf-etica","hf-politica","hf-helenismo","hf-medieval","hf-fe-razon","hf-aristoteles-arabe","hf-verdad-no-contradice","hf-islam-ideas","hf-toledo-traductores","hf-judios-andalus","hf-cinco-vias","hf-modernidad","hf-montaigne-ensayos","hf-renacimiento-magia","hf-contrato","hf-utilitarismo","hf-kant-juicios","hf-descartes-makro"]},"mencio":{"name":"Mencio","dates":"c. 372 – 289 a. C.","born":-372,"died":-289,"place":"Estado de Zou (China)","role":"pensador confuciano chino","idea":"El ser humano es bueno por naturaleza: todos llevamos dentro los brotes de la compasión y de la justicia, y la educación los hace crecer.","obras":["Mencio (Mengzi), recopilación de sus diálogos"],"fuente":"Liu Xiang, Biografías de mujeres ejemplares (s. I a. C.)","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-beefs"]},"teofrasto":{"name":"Teofrasto de Ereso","dates":"c. 371 – c. 287 a. C.","born":-371,"died":-287,"place":"Ereso (isla de Lesbos)","role":"filósofo peripatético y naturalista","idea":"Para entender la naturaleza hay que observarla con detalle y clasificarla, planta por planta y carácter por carácter.","obras":["Historia de las plantas","Causas de las plantas","Caracteres"],"block":"ant","subjects":["hf"],"temas":["hf-preso","hf-aristoteles-arabe","hf-kant-juicios"]},"crates":{"name":"Crates de Tebas","dates":"c. 365 – c. 285 a. C.","born":-365,"died":-285,"place":"Tebas (Beocia)","role":"filósofo cínico","idea":"La felicidad está en necesitar muy poco: quien renuncia a la riqueza y a la opinión ajena es libre.","obras":[],"block":"ant","subjects":["hf"],"temas":["hf-helenismo"]},"pirron":{"name":"Pirrón de Elis","dates":"c. 360 – c. 270 a. C.","born":-360,"died":-270,"place":"Elis (Peloponeso)","role":"filósofo escéptico","idea":"A toda afirmación puede oponerse otra igual de convincente; por eso el sabio suspende el juicio y así alcanza la tranquilidad del alma.","obras":[],"fuente":"Diógenes Laercio, Vidas IX","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-helenismo","hf-montaigne-ensayos","hf-bayle-diccionario","hf-descartes-makro"]},"hiparquia":{"name":"Hiparquía de Maronea","dates":"c. 350 – c. 280 a. C.","born":-350,"died":-280,"place":"Maronea (Tracia); vivió en Atenas","role":"filósofa cínica","idea":"Vivió hasta el final la filosofía cínica que predicaba: renunció a la riqueza y al papel que su época reservaba a las mujeres para vivir según la naturaleza, en igualdad con su compañero Crates.","obras":["Hipótesis filosóficas (perdida)","Epiqueremas (perdida)","Cuestiones a Teodoro el Ateo (perdida)"],"fuente":"Diógenes Laercio, *Vidas de los filósofos ilustres* VI (vida de Crates); los títulos de sus obras perdidas proceden de la *Suda* (s.v. Hiparquía); epigrama de Antípatro de Sidón, *Antología Palatina* VII, 413; adaptado de Lola Cabrera Trigo, *El pensamiento en femenino plural* (Erein, serie «En diálogo con…»; CC BY-NC-SA 4.0)","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-filosofas-dialogo"]},"epicuro":{"name":"Epicuro","dates":"341 – 270 a. C.","born":-341,"died":-270,"place":"Samos","role":"filósofo griego helenístico","idea":"La felicidad es el placer entendido como ausencia de dolor en el cuerpo y de turbación en el alma, que se logra con moderación, amistad y sin miedos.","obras":["Carta a Meneceo","Carta a Heródoto","Máximas capitales"],"fuente":"Séneca, Cartas a Lucilio 21; Diógenes Laercio, Vidas X","tradicion":false,"block":"ant","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-helenismo","hf-montaigne-ensayos"]},"straton":{"name":"Estratón de Lámpsaco","dates":"c. 335 – c. 269 a. C.","born":-335,"died":-269,"place":"Lámpsaco (junto al Helesponto)","role":"filósofo peripatético, «el Físico»","idea":"La naturaleza se explica por sus propias fuerzas, sin necesidad de dioses ni de fines.","obras":[],"block":"ant","subjects":["hf"],"temas":[]},"zenon":{"name":"Zenón de Citio","dates":"c. 334 – c. 262 a. C.","born":-334,"died":-262,"place":"Citio (Chipre)","role":"filósofo fundador del estoicismo","idea":"El universo está ordenado por una razón divina; el sabio acepta el destino, domina sus pasiones y solo se preocupa de lo que depende de él.","obras":[],"fuente":"Diógenes Laercio, Vidas VII","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-helenismo"]},"cleantes":{"name":"Cleantes de Aso","dates":"c. 331 – c. 232 a. C.","born":-331,"died":-232,"place":"Aso (Asia Menor)","role":"filósofo estoico","idea":"Un mismo lógos, la razón divina, gobierna el universo; vivir bien es vivir de acuerdo con él y aceptar el destino.","obras":["Himno a Zeus"],"block":"ant","subjects":["hf"],"temas":[]},"timon":{"name":"Timón de Fliunte","dates":"c. 320 – c. 230 a. C.","born":-320,"died":-230,"place":"Fliunte (Peloponeso)","role":"filósofo escéptico y poeta satírico","idea":"Quien quiere ser feliz debe preguntarse cómo son las cosas, qué actitud tomar ante ellas y qué gana con esa actitud; la respuesta escéptica es suspender el juicio.","obras":["Silos"],"block":"ant","subjects":["hf"],"temas":[]},"arcesilao":{"name":"Arcesilao de Pitane","dates":"c. 316 – c. 241 a. C.","born":-316,"died":-241,"place":"Pitane (Asia Menor)","role":"filósofo académico escéptico","idea":"No hay ningún criterio seguro para distinguir lo verdadero de lo falso; por eso el sabio suspende el juicio.","obras":[],"block":"ant","subjects":["hf"],"temas":[]},"crisipo":{"name":"Crisipo de Solos","dates":"c. 279 – c. 206 a. C.","born":-279,"died":-206,"place":"Solos (Cilicia, Asia Menor)","role":"filósofo estoico","idea":"Todo ocurre según el destino, pero lo que hacemos depende también de nosotros, como un cilindro que rueda según su forma cuando alguien lo empuja.","obras":[],"block":"ant","subjects":["hf"],"temas":["hf-kant-juicios"]},"carneades":{"name":"Carnéades de Cirene","dates":"c. 214 – c. 129 a. C.","born":-214,"died":-129,"place":"Cirene (norte de África)","role":"filósofo académico escéptico","idea":"No podemos alcanzar la verdad segura, pero sí distinguir lo más o menos probable, y eso basta para decidir cómo actuar.","obras":[],"block":"ant","subjects":["hf"],"temas":["hf-helenismo"]},"ciceron":{"name":"Marco Tulio Cicerón","dates":"106 – 43 a. C.","born":-106,"died":-43,"place":"Arpino (Lacio, Italia)","role":"orador, político y filósofo romano","idea":"La filosofía griega se puede pensar en latín: Cicerón la tradujo para los romanos y expuso las escuelas como un debate en el que el lector tiene que decidir.","obras":["Sobre la república","Disputas tusculanas","Sobre la naturaleza de los dioses","Sobre los deberes"],"fuente":"Plutarco, Vida de Cicerón 47-49","tradicion":false,"block":"ant","subjects":["hf"],"temas":["hf-politica","hf-cinco-vias"]},"seneca":{"name":"Séneca","dates":"c. 4 a. C. – 65 d. C.","born":-4,"died":65,"place":"Córdoba (Hispania)","role":"filósofo estoico romano","idea":"No controlamos lo que nos sucede, pero sí cómo lo afrontamos; la sabiduría consiste en dominar las pasiones y aprovechar bien el tiempo de la vida.","obras":["Cartas a Lucilio","Sobre la brevedad de la vida","Sobre la ira","Sobre la felicidad"],"fuente":"Séneca, Sobre la ira III","tradicion":false,"block":"ant","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-helenismo","hf-montaigne-ensayos"]},"quintiliano":{"name":"Quintiliano","dates":"c. 35 – c. 100 d. C.","born":35,"died":100,"place":"Calagurris (Hispania; actual Calahorra, La Rioja)","role":"retórico y pedagogo romano","idea":"El fin de la educación es formar al orador perfecto, que no es solo quien habla bien, sino el «hombre bueno experto en el decir»: sin honradez no hay verdadera elocuencia.","obras":["Instituciones oratorias (Institutio oratoria, o Sobre la formación del orador)"],"fuente":"Quintiliano, Instituciones oratorias VI, proemio (la frase «vir bonus dicendi peritus», en XII, 1; traducción propia del latín)","tradicion":false,"block":"ant","subjects":["hf"],"temas":["hf-filosofia-espanola"]},"epicteto":{"name":"Epicteto","dates":"c. 50 – c. 135","born":50,"died":135,"place":"Hierápolis (Frigia, actual Turquía)","role":"filósofo estoico griego","idea":"Hay cosas que dependen de nosotros, nuestros juicios y decisiones, y cosas que no; la libertad consiste en no hacer depender la felicidad de lo que no depende de nosotros.","obras":["Disertaciones (recogidas por Arriano)","Manual o Enquiridion (resumen de Arriano)"],"fuente":"Orígenes, Contra Celso VII, 53","tradicion":true,"block":"ant","subjects":["hf"],"temas":["hf-helenismo"]},"marco_aurelio":{"name":"Marco Aurelio","dates":"121 – 180","born":121,"died":180,"place":"Roma","role":"emperador romano y filósofo estoico","idea":"Cada día hay que cumplir con el propio deber, aceptar con serenidad lo que no depende de nosotros y recordar que todo es pasajero.","obras":["Meditaciones o A sí mismo (escritas hacia 170-180)"],"fuente":"Marco Aurelio, Meditaciones I, 7 y I, 17","tradicion":false,"block":"ant","subjects":["hf"],"temas":["hf-helenismo"]},"tertuliano":{"name":"Tertuliano","dates":"c. 155 – c. 220","born":155,"died":220,"place":"Cartago (actual Túnez)","role":"apologista cristiano","idea":"La fe cristiana no necesita el apoyo de la filosofía griega: lo revelado debe creerse aunque la razón humana no lo comprenda o lo juzgue absurdo.","obras":["Apologético (197)","Sobre la prescripción de los herejes","Sobre la carne de Cristo"],"block":"ant","subjects":["hf"],"temas":["hf-fe-razon"]},"plotino":{"name":"Plotino","dates":"205 – 270","born":205,"died":270,"place":"Licópolis (Egipto)","role":"filósofo neoplatónico","idea":"Toda la realidad procede del Uno por emanación necesaria, en grados decrecientes de perfección, y el alma puede volver a él mediante la contemplación y la purificación.","obras":["Enéadas"],"fuente":"Porfirio, Vida de Plotino","tradicion":false,"block":"ant","subjects":["hf"],"temas":["hf-fe-razon","hf-aristoteles-arabe","hf-renacimiento-magia"]},"agustin":{"name":"Agustín de Hipona","dates":"354 – 430","born":354,"died":430,"place":"Tagaste (actual Argelia)","role":"filósofo y teólogo cristiano","idea":"La verdad no se busca fuera sino en el interior del alma, donde Dios la ilumina; la fe guía a la razón para que pueda comprender.","obras":["Confesiones (c. 397-400)","La ciudad de Dios (413-426)","Sobre la Trinidad","Sobre el libre albedrío"],"fuente":"Agustín de Hipona, Confesiones VIII","tradicion":false,"vida":[{"a":373,"b":383,"t":"Etapa maniquea"},{"a":384,"b":386,"t":"En Milán, con Ambrosio"},{"a":386,"t":"Conversión"},{"a":387,"t":"Bautismo"},{"a":395,"b":430,"t":"Obispo de Hipona"}],"block":"med","subjects":["hf"],"temas":["hf-medieval","hf-platon-agustin","hf-fe-razon","hf-verdad-no-contradice","hf-islam-ideas","hf-toledo-traductores","hf-cinco-vias","hf-montaigne-ensayos","hf-renacimiento-magia","hf-racionalismo","hf-descartes-makro"]},"hipatia":{"name":"Hipatia de Alejandría","dates":"c. 355/370 – 415 d. C.","born":355,"died":415,"place":"Alejandría (Egipto)","role":"matemática, astrónoma y filósofa","idea":"Unió la filosofía neoplatónica con la enseñanza de las matemáticas y la astronomía, entendiendo el estudio racional del cosmos como camino hacia la sabiduría.","obras":[],"fuente":"Damascio, Vida de Isidoro (fragmentos en la Suda); Sócrates Escolástico, Historia eclesiástica VII","tradicion":false,"block":"ant","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-helenismo"]},"boecio":{"name":"Boecio","dates":"c. 480 – 524","born":480,"died":524,"place":"Roma","role":"filósofo y político romano","idea":"La verdadera felicidad no está en los bienes de la fortuna, que van y vienen, sino en el bien perfecto, que es Dios: si hay bienes imperfectos, tiene que haber uno perfecto.","obras":["Consolación de la filosofía (hacia 524)","Traducciones y comentarios de la lógica de Aristóteles","Comentarios a la Introducción de Porfirio"],"fuente":"Boecio, Consolación de la filosofía I, prosas 1 y 3","tradicion":false,"block":"med","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-aristoteles-arabe","hf-toledo-traductores","hf-cinco-vias","hf-kant-juicios"]},"isidoro":{"name":"Isidoro de Sevilla","dates":"c. 556 – 636","born":556,"died":636,"place":"Cartagena (Hispania; obispo en Sevilla)","role":"obispo, enciclopedista y Padre de la Iglesia","idea":"Reunir y ordenar todo el saber de la Antigüedad para salvarlo en una época de ruina; su método es la etimología, porque conocer de dónde viene el nombre de algo ayuda a entender la cosa misma.","obras":["Etimologías (Etymologiae u Orígenes)","Sobre la naturaleza de las cosas (De natura rerum)","Historia de los godos (Historia Gothorum)","Sentencias (Sententiae)"],"fuente":"ACI Prensa, «¿Quién es el patrono de internet?»; Word on Fire, «The Patron Saint of the Internet»; el nombramiento no es oficial","tradicion":false,"block":"med","subjects":["hf"],"temas":["hf-filosofia-espanola"]},"al_kindi":{"name":"Al-Kindi","dates":"c. 801 – c. 873","born":801,"died":873,"place":"Kufa (actual Irak)","role":"filósofo y científico árabe","idea":"La verdad hay que aceptarla venga de donde venga, aunque sea de pueblos lejanos: la filosofía de los griegos y la fe del islam no se oponen.","obras":["Sobre la filosofía primera","Tratado sobre el desciframiento de mensajes cifrados","Sobre el intelecto"],"fuente":"Ibn Abi Usaybia, Fuentes de noticias sobre las clases de médicos (siglo XIII)","tradicion":true,"block":"med","subjects":["hf"],"temas":["hf-aristoteles-arabe","hf-verdad-no-contradice","hf-cinco-vias"]},"escoto_erigena":{"name":"Juan Escoto Erígena","dates":"c. 810 – c. 877","born":810,"died":877,"place":"Irlanda","role":"filósofo y teólogo","idea":"La verdadera filosofía es la verdadera religión, y al revés; toda la naturaleza sale de Dios y vuelve a Él.","obras":["Sobre la división de la naturaleza (Periphyseon)"],"fuente":"Guillermo de Malmesbury, Hechos de los obispos ingleses","tradicion":true,"block":"med","subjects":["hf"],"temas":[]},"avicena":{"name":"Avicena","dates":"980 – 1037","born":980,"died":1037,"place":"Afshana, cerca de Bujará (actual Uzbekistán)","role":"filósofo y médico persa","idea":"En todas las cosas creadas se distingue lo que son (esencia) de que existan (existencia); solo en Dios coinciden: Él es el ser necesario.","obras":["Canon de medicina","Libro de la curación"],"fuente":"Avicena, Autobiografía","tradicion":false,"block":"med","subjects":["hf"],"temas":["hf-medieval","hf-fe-razon","hf-aristoteles-arabe","hf-verdad-no-contradice","hf-islam-ideas","hf-toledo-traductores","hf-judios-andalus","hf-cinco-vias","hf-renacimiento-magia","hf-kant-juicios"]},"anselmo":{"name":"Anselmo de Canterbury","dates":"1033 – 1109","born":1033,"died":1109,"place":"Aosta (Italia)","role":"filósofo y teólogo escolástico","idea":"Dios es aquello mayor que lo cual nada puede pensarse; por eso no puede existir solo en la mente, sino que debe existir también en la realidad.","obras":["Monologion (1076)","Proslogion (1077-1078)","Por qué Dios se hizo hombre"],"fuente":"Eadmero, Vida de san Anselmo","tradicion":false,"block":"med","subjects":["hf"],"temas":["hf-medieval","hf-fe-razon","hf-cinco-vias","hf-racionalismo"]},"al_ghazali":{"name":"Al-Ghazali","dates":"1058 – 1111","born":1058,"died":1111,"place":"Tus (Persia, actual Irán)","role":"teólogo, jurista y místico musulmán","idea":"La razón de los filósofos no demuestra todo lo que pretende: tesis como la eternidad del mundo no están probadas, y la certeza más honda llega por la experiencia interior.","obras":["Las intenciones de los filósofos","La incoherencia de los filósofos (hacia 1095)","La revivificación de las ciencias religiosas","El salvador del error"],"fuente":"Al-Ghazali, El salvador del error (relato autobiográfico)","tradicion":false,"block":"med","subjects":["hf"],"temas":["hf-beefs","hf-aristoteles-arabe","hf-verdad-no-contradice","hf-islam-ideas","hf-toledo-traductores","hf-cinco-vias","hf-kant-juicios"]},"abelardo":{"name":"Pedro Abelardo","dates":"1079 – 1142","born":1079,"died":1142,"place":"Le Pallet (Bretaña, Francia)","role":"filósofo y lógico escolástico","idea":"Los universales no son cosas reales ni meras palabras, sino conceptos de la mente que expresan lo que tienen en común los individuos.","obras":["Sí y no (Sic et non)","Historia de mis desgracias","Ética o Conócete a ti mismo","Diálogo entre un filósofo, un judío y un cristiano"],"fuente":"Pedro Abelardo, Historia de mis desgracias","tradicion":false,"block":"med","subjects":["hf"],"temas":["hf-medieval","hf-kant-juicios"]},"avempace":{"name":"Avempace","dates":"c. 1085 – 1138","born":1085,"died":1138,"place":"Zaragoza (al-Ándalus)","role":"filósofo, médico y músico andalusí","idea":"En una sociedad imperfecta, el sabio debe vivir como un «solitario», cultivando el entendimiento hasta unirse con el intelecto que ilumina a todos los seres humanos.","obras":["El régimen del solitario","Comentarios a la Física de Aristóteles"],"block":"med","subjects":["hf"],"temas":["hf-aristoteles-arabe","hf-verdad-no-contradice"]},"hildegarda":{"name":"Hildegarda de Bingen","dates":"1098 – 1179","born":1098,"died":1179,"place":"Bermersheim (Renania, Alemania)","role":"abadesa, mística y compositora","idea":"El ser humano es un microcosmos que refleja el orden del universo creado por Dios, de modo que fe, ciencia natural y arte forman un único saber.","obras":["Scivias (1141-1151)","Física (Physica)","Causas y remedios","Ordo Virtutum"],"fuente":"Carta de Hildegarda a los prelados de Maguncia; Vida de santa Hildegarda","tradicion":false,"vida":[{"a":1141,"b":1151,"t":"Escribe Scivias"},{"a":1158,"b":1163,"t":"Escribe Liber vitae meritorum"},{"a":1163,"b":1174,"t":"Escribe Liber divinorum operum"}],"block":"med","subjects":["hf"],"temas":["hf-medieval"]},"eloisa":{"name":"Eloísa","dates":"c. 1100 – 1164","born":1100,"died":1164,"place":"Francia (probablemente París)","role":"filósofa, escritora y abadesa","idea":"Lo que cuenta moralmente es la intención con la que se actúa, no lo que se ve desde fuera; y el amor verdadero no busca nada a cambio, ni siquiera el matrimonio.","obras":["Cartas (correspondencia con Abelardo)","Problemas de Eloísa"],"fuente":"Crónica de Tours (s. XIII), para la leyenda del abrazo","tradicion":true,"block":"med","subjects":["hf"],"temas":[]},"averroes":{"name":"Averroes","dates":"1126 – 1198","born":1126,"died":1198,"place":"Córdoba (al-Ándalus)","role":"filósofo, jurista y médico andalusí","idea":"La verdad no puede contradecir a la verdad: la demostración filosófica y la revelación coinciden, aunque cada una se dirige a un tipo distinto de personas.","obras":["Doctrina decisiva","La incoherencia de la incoherencia","Comentarios a Aristóteles","Libro de las generalidades de la medicina"],"fuente":"Al-Marrakushi, Historia de los almohades (Kitab al-Muyib)","tradicion":false,"block":"med","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-filosofia-espanola","hf-beefs","hf-aa","hf-antropologia","hf-medieval","hf-fe-razon","hf-aristoteles-arabe","hf-verdad-no-contradice","hf-toledo-traductores","hf-cinco-vias","hf-montaigne-ensayos"]},"maimonides":{"name":"Maimónides","dates":"1138 – 1204","born":1138,"died":1204,"place":"Córdoba (al-Ándalus)","role":"filósofo, médico y rabino","idea":"La fe y la razón no se contradicen; la Biblia debe leerse a la luz de la razón, y de Dios solo podemos decir lo que no es.","obras":["Guía de perplejos","Mishné Torá"],"block":"med","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-aa","hf-aristoteles-arabe","hf-verdad-no-contradice","hf-islam-ideas","hf-judios-andalus","hf-cinco-vias","hf-renacimiento-magia"]},"alberto_magno":{"name":"Alberto Magno","dates":"c. 1200 – 1280","born":1200,"died":1280,"place":"Lauingen (Baviera, Alemania)","role":"filósofo, teólogo y naturalista dominico","idea":"La fe y la razón tienen cada una su campo: la naturaleza se conoce observándola y razonando, sin necesidad de recurrir a milagros.","obras":["Sobre los vegetales","Sobre los animales","Comentarios a Aristóteles"],"fuente":"Guillermo de Tocco, Vida de santo Tomás de Aquino","tradicion":true,"block":"med","subjects":["hf"],"temas":[]},"buenaventura":{"name":"Buenaventura","dates":"c. 1217 – 1274","born":1217,"died":1274,"place":"Bagnoregio (Italia)","role":"teólogo y filósofo franciscano","idea":"Todo saber debe llevar a Dios: el mundo es como un libro lleno de huellas de su autor, y la mente sube por ellas como por una escalera.","obras":["Itinerario de la mente hacia Dios (1259)","Comentario a las Sentencias","Breviloquio","Lecciones sobre el Hexámeron (1273)"],"fuente":"Tradición franciscana posterior (no aparece en los documentos de su época)","tradicion":true,"block":"med","subjects":["hf"],"temas":["hf-cinco-vias"]},"roger_bacon":{"name":"Roger Bacon","dates":"c. 1220 – c. 1292","born":1220,"died":1292,"place":"Ilchester (Inglaterra)","role":"filósofo y científico franciscano","idea":"Sin experiencia no se puede saber nada con seguridad: la ciencia necesita comprobar sus afirmaciones y apoyarse en las matemáticas.","obras":["Obra mayor (Opus maius)","Obra menor","Obra tercera"],"block":"med","subjects":["hf"],"temas":[]},"tomas":{"name":"Tomás de Aquino","dates":"1225 – 1274","born":1225,"died":1274,"place":"Roccasecca (Italia)","role":"filósofo y teólogo escolástico","idea":"Fe y razón no se contradicen, sino que colaboran: la razón demuestra la existencia de Dios a partir de la experiencia y prepara el camino a la fe.","obras":["Suma teológica (1265-1274)","Suma contra los gentiles","El ente y la esencia"],"fuente":"Guillermo de Tocco, Historia de santo Tomás de Aquino","tradicion":true,"vida":[{"a":1259,"b":1265,"t":"Escribe la Summa contra Gentiles"},{"a":1265,"b":1274,"t":"Escribe la Summa Theologiae"}],"block":"med","subjects":["hf"],"temas":["hf-historicidad","hf-beefs","hf-aa","hf-antropologia","hf-medieval","hf-fe-razon","hf-aristoteles-arabe","hf-verdad-no-contradice","hf-toledo-traductores","hf-judios-andalus","hf-cinco-vias","hf-montaigne-ensayos"]},"llull":{"name":"Ramon Llull","dates":"c. 1232 – c. 1316","born":1232,"died":1316,"place":"Palma (Mallorca)","role":"filósofo, místico y escritor","idea":"Combinando unos pocos conceptos básicos se pueden demostrar las verdades de la fe a cualquiera, sea cristiano, musulmán o judío, solo con la razón.","obras":["Arte magna","Libro del gentil y los tres sabios","Blanquerna"],"block":"med","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-renacimiento-magia"]},"porete":{"name":"Margarita Porete","dates":"c. 1250 – 1310","born":1250,"died":1310,"place":"Hainaut (hoy entre Bélgica y el norte de Francia)","role":"mística y beguina","idea":"Sostuvo que el alma que ama puede unirse a Dios por el amor y la libertad, sin necesidad del clero ni de los sacramentos; murió en la hoguera por no retractarse de su libro.","obras":["El espejo de las almas simples (Le Mirouer des simples âmes)"],"fuente":"Margarita Porete, *El espejo de las almas simples*; actas del proceso inquisitorial de París (1310); adaptado de Lola Cabrera Trigo, *El pensamiento en femenino plural* (Erein, serie «En diálogo con…»; CC BY-NC-SA 4.0)","tradicion":true,"block":"med","subjects":["hf"],"temas":["hf-filosofas-dialogo"]},"dante":{"name":"Dante Alighieri","dates":"1265 – 1321","born":1265,"died":1321,"place":"Florencia (Italia)","role":"poeta y pensador político","idea":"El ser humano tiene dos fines, la felicidad en esta vida y en la otra; para la primera hace falta un emperador que garantice la paz, independiente del papa.","obras":["Divina Comedia","Convivio","Monarquía"],"block":"med","subjects":["hf"],"temas":["hf-aristoteles-arabe"]},"duns_escoto":{"name":"Juan Duns Escoto","dates":"c. 1266 – 1308","born":1266,"died":1308,"place":"Duns (Escocia)","role":"filósofo y teólogo franciscano","idea":"Cada individuo tiene algo propio que lo hace único, su «esteidad»; y en Dios y en el ser humano la voluntad está por encima del entendimiento.","obras":["Ordinatio","Tratado del primer principio"],"block":"med","subjects":["hf"],"temas":["hf-cinco-vias"]},"ockham":{"name":"Guillermo de Ockham","dates":"c. 1287 – 1347","born":1287,"died":1347,"place":"Ockham (Surrey, Inglaterra)","role":"filósofo y teólogo franciscano","idea":"Solo existen los individuos y no deben multiplicarse los entes sin necesidad; la razón no puede demostrar las verdades de la fe.","obras":["Suma de lógica (c. 1323)","Comentario a las Sentencias","Quodlibetos","Diálogo"],"fuente":"Frase atribuida por la tradición posterior; no consta en sus escritos","tradicion":true,"vida":[{"a":1324,"t":"Llamado a Aviñón por sospecha de herejía"},{"a":1328,"t":"Huye a Múnich, con el emperador Luis de Baviera"}],"block":"med","subjects":["hf"],"temas":["hf-beefs","hf-medieval","hf-fe-razon","hf-cinco-vias","hf-modernidad"]},"pizan":{"name":"Christine de Pizan","dates":"1364 – c. 1430","born":1364,"died":1430,"place":"Venecia; vivió en la corte de Francia","role":"escritora y pensadora","idea":"Primera mujer de Europa que vivió de su pluma; en *La ciudad de las damas* rebatió con argumentos la misoginia de su época y defendió la dignidad y la capacidad intelectual de las mujeres.","obras":["La ciudad de las damas","El libro de las tres virtudes","La epístola al dios Amor","Canción en honor de Juana de Arco (Ditié de Jehanne d'Arc)"],"fuente":"Christine de Pizan, *La ciudad de las damas*; Simone de Beauvoir, *El segundo sexo* (introducción); adaptado de Lola Cabrera Trigo, *El pensamiento en femenino plural* (Erein, serie «En diálogo con…»; CC BY-NC-SA 4.0)","tradicion":true,"block":"med","subjects":["hf"],"temas":["hf-utopias-autoras","hf-filosofas-dialogo"]},"nicolas_cusa":{"name":"Nicolás de Cusa","dates":"1401 – 1464","born":1401,"died":1464,"place":"Kues (junto al Mosela, Alemania)","role":"filósofo, teólogo y cardenal","idea":"Lo más alto que podemos saber es que no sabemos: una «docta ignorancia»; en Dios, infinito, coinciden los opuestos.","obras":["La docta ignorancia","La paz de la fe"],"block":"ren","subjects":["hf"],"temas":["hf-renacimiento-magia"]},"leonardo":{"name":"Leonardo da Vinci","dates":"1452 – 1519","born":1452,"died":1519,"place":"Vinci (Toscana, Italia)","role":"artista, ingeniero e investigador del Renacimiento","idea":"La experiencia es la madre del conocimiento: para entender la naturaleza hay que observarla, medirla y dibujarla, en lugar de fiarse solo de los libros.","obras":["La última cena (1495-1498)","Hombre de Vitruvio (c. 1490)","La Gioconda (c. 1503-1519)","Cuadernos de notas (Códice Atlántico, Códice Leicester y otros)"],"fuente":"Cuadernos de Leonardo (Códice Atlántico, Biblioteca Ambrosiana de Milán)","tradicion":false,"block":"ren","subjects":["hf"],"temas":[]},"pico":{"name":"Giovanni Pico della Mirandola","dates":"1463 – 1494","born":1463,"died":1494,"place":"Mirandola (Italia)","role":"humanista y filósofo","idea":"El ser humano no tiene una naturaleza fija: puede elegir lo que quiere ser, rebajarse hasta las bestias o elevarse hasta lo divino.","obras":["Discurso sobre la dignidad del hombre","900 tesis"],"block":"ren","subjects":["hf"],"temas":["hf-modernidad","hf-renacimiento-magia"]},"erasmo":{"name":"Erasmo de Róterdam","dates":"c. 1466 – 1536","born":1466,"died":1536,"place":"Róterdam (Países Bajos)","role":"humanista y teólogo","idea":"La verdadera religión es vivir con bondad y en paz siguiendo el Evangelio, no las ceremonias ni las disputas de los teólogos; y para ello hace falta leer bien los textos y educar.","obras":["Elogio de la locura","Manual del caballero cristiano","Sobre el libre albedrío","Lamento de la paz"],"fuente":"Erasmo, carta a Johannes Caesarius (1524)","tradicion":true,"block":"ren","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-beefs","hf-modernidad"]},"maquiavelo":{"name":"Nicolás Maquiavelo","dates":"1469 – 1527","born":1469,"died":1527,"place":"Florencia (Italia)","role":"pensador político y diplomático","idea":"La política debe estudiarse tal como es y no como debería ser: es una técnica autónoma, separada de la moral y de la religión, cuyo fin es conservar el Estado.","obras":["El príncipe (1513)","Discursos sobre la primera década de Tito Livio","Del arte de la guerra (1521)","La mandrágora"],"fuente":"Maquiavelo, carta a Francesco Vettori del 10 de diciembre de 1513","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-modernidad","hf-contrato"]},"copernico":{"name":"Nicolás Copérnico","dates":"1473 – 1543","born":1473,"died":1543,"place":"Toruń (Polonia)","role":"astrónomo y matemático","idea":"La Tierra no es el centro inmóvil del universo, sino que gira sobre sí misma y alrededor del Sol, como los demás planetas.","obras":["Sobre las revoluciones de las esferas celestes (1543)"],"fuente":"Carta de Tiedemann Giese a Rheticus (1543)","tradicion":true,"block":"ren","subjects":["hf"],"temas":["hf-modernidad","hf-renacimiento-magia","hf-sospecha","hf-analitica","hf-descartes-makro"]},"tomas_moro":{"name":"Tomás Moro","dates":"1478 – 1535","born":1478,"died":1535,"place":"Londres (Inglaterra)","role":"humanista, jurista y político","idea":"Una sociedad justa exige acabar con la propiedad privada y organizar el trabajo de todos para que nadie pase necesidad.","obras":["Utopía"],"fuente":"William Roper, Vida de sir Tomás Moro; Edward Hall, Crónica","tradicion":true,"block":"ren","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-modernidad","hf-utopias-autoras"]},"lutero":{"name":"Martín Lutero","dates":"1483 – 1546","born":1483,"died":1546,"place":"Eisleben (Sajonia, Alemania)","role":"teólogo y reformador religioso","idea":"El ser humano se salva solo por la fe, y cada creyente puede leer e interpretar directamente la Biblia sin depender de la autoridad de la Iglesia.","obras":["Las 95 tesis (1517)","La libertad del cristiano (1520)","A la nobleza cristiana de la nación alemana (1520)","La voluntad esclava (1525)"],"fuente":"Testimonios del propio Lutero (Charlas de sobremesa)","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-beefs","hf-modernidad","hf-descartes-makro"]},"vitoria":{"name":"Francisco de Vitoria","dates":"c. 1483 – 1546","born":1483,"died":1546,"place":"Burgos o Vitoria","role":"teólogo y jurista dominico","idea":"Hay un derecho común a todos los pueblos, también a los de América: ni la diferencia de religión ni la de costumbres justifica por sí sola conquistarlos o quitarles sus tierras.","obras":["Sobre los indios (Relectio de Indis, 1539)","Sobre el derecho de guerra (Relectio de iure belli, 1539)","Relecciones teológicas (recogidas por sus alumnos)"],"fuente":"Las relecciones De Indis y De iure belli se conservan y editan a partir de los manuscritos de sus alumnos; Vitoria no publicó en vida (dato recogido en las ediciones críticas de sus Relectiones)","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-euskal-herria","hf-filosofia-espanola"]},"las_casas":{"name":"Bartolomé de las Casas","dates":"c. 1484 – 1566","born":1484,"died":1566,"place":"Sevilla","role":"fraile dominico, defensor de los indígenas americanos","idea":"Los indígenas de América son seres humanos libres y racionales, con los mismos derechos que cualquiera; conquistarlos y esclavizarlos por la fuerza es una injusticia.","obras":["Brevísima relación de la destrucción de las Indias (1552)","Historia de las Indias","Apología (defensa leída en la controversia de Valladolid, 1550)"],"fuente":"Bartolomé de las Casas, Historia de las Indias (relato de su propia conversión, hacia 1514)","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-beefs"]},"sepulveda":{"name":"Juan Ginés de Sepúlveda","dates":"c. 1490 – 1573","born":1490,"died":1573,"place":"Pozoblanco (Córdoba)","role":"humanista, cronista real y traductor de Aristóteles","idea":"Apoyándose en Aristóteles, defendió que algunos pueblos son por naturaleza más aptos para mandar y otros para obedecer, y que por eso la guerra contra los indígenas podía ser justa.","obras":["Demócrates segundo o De las justas causas de la guerra contra los indios (Democrates alter, h. 1544)","Traducciones latinas de Aristóteles (Política, entre otras)","Crónicas de Carlos V"],"fuente":"Historia de la censura del Demócrates segundo: los dictámenes de Salamanca y Alcalá (hacia 1548) desaconsejaron su impresión, recogido en las ediciones modernas de la obra","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-beefs"]},"vives":{"name":"Juan Luis Vives","dates":"1493 – 1540","born":1493,"died":1540,"place":"Valencia","role":"humanista y pedagogo valenciano","idea":"La educación debe partir de la experiencia y de la observación de cada persona, y alcanzar también a las mujeres y a los pobres, no solo a una minoría culta.","obras":["La formación de la mujer cristiana (De institutione feminae christianae, 1523)","El socorro de los pobres (De subventione pauperum, 1526)","De las disciplinas (De disciplinis, 1531)","Del alma y de la vida (De anima et vita, 1538)"],"fuente":"Investigaciones de Miguel de la Pinta Llorente y José María de Palacio sobre los procesos inquisitoriales de la familia Vives (archivos del siglo XVI, publicados en 1964)","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-filosofia-espanola"]},"calvino":{"name":"Juan Calvino","dates":"1509 – 1564","born":1509,"died":1564,"place":"Noyon (Picardía, Francia)","role":"teólogo y reformador protestante","idea":"Dios, soberano absoluto, ha predestinado desde la eternidad quiénes se salvarán, y el creyente debe vivir con disciplina y responsabilidad según su palabra.","obras":["Institución de la religión cristiana (1536)"],"fuente":"Calvino, prefacio al Comentario de los Salmos","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-filosofia-espanola","hf-descartes-makro"]},"servet":{"name":"Miguel Servet","dates":"1511 – 1553","born":1511,"died":1553,"place":"Villanueva de Sijena (Aragón)","role":"médico y teólogo aragonés","idea":"Defendió que no hay base para el dogma de la Trinidad y reclamó libertad para pensar en religión; también describió cómo la sangre pasa por los pulmones.","obras":["Sobre los errores de la Trinidad (De Trinitatis erroribus, 1531)","Restitución del cristianismo (Christianismi restitutio, 1553)"],"fuente":"Miguel Servet, Christianismi restitutio (1553), donde se describe la circulación pulmonar; de los pocos ejemplares que escaparon a la quema","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-filosofia-espanola"]},"montaigne":{"name":"Michel de Montaigne","dates":"1533 – 1592","born":1533,"died":1592,"place":"Castillo de Montaigne (Périgord, Francia)","role":"humanista y ensayista francés","idea":"El mejor tema de estudio es uno mismo: examinando con honradez su propia vida, cambiante y contradictoria, se aprende qué es ser humano y lo poco que sabemos con certeza.","obras":["Ensayos (1580; ampliados en 1588; edición póstuma de 1595)","Diario de viaje a Italia (escrito en 1580-1581, publicado en 1774)"],"fuente":"Inscripciones de la torre de Montaigne (1571)","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-montaigne-ensayos","hf-utopias-autoras","hf-bayle-diccionario","hf-kant-poetas"]},"giordano_bruno":{"name":"Giordano Bruno","dates":"1548 – 1600","born":1548,"died":1600,"place":"Nola (cerca de Nápoles, Italia)","role":"filósofo y cosmólogo","idea":"El universo es infinito y está lleno de infinitos mundos; cada estrella es un sol con sus propios planetas.","obras":["Sobre el infinito universo y los mundos","La cena de las cenizas","De la causa, principio y uno"],"block":"ren","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-renacimiento-magia"]},"suarez":{"name":"Francisco Suárez","dates":"1548 – 1617","born":1548,"died":1617,"place":"Granada","role":"teólogo y filósofo jesuita","idea":"El poder político no baja directamente de Dios al rey, sino que Dios lo pone en el pueblo, y el pueblo lo entrega a quien gobierna; por eso el poder tiene límites.","obras":["Disputaciones metafísicas (Disputationes metaphysicae, 1597)","Sobre las leyes (De legibus, 1612)","Defensa de la fe católica (Defensio fidei catholicae, 1613)"],"fuente":"Hecho recogido en las biografías de Suárez y en los estudios sobre la Defensio fidei (1613), condenada a la quema en Londres y en París","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-filosofia-espanola"]},"francis_bacon":{"name":"Francis Bacon","dates":"1561 – 1626","born":1561,"died":1626,"place":"Londres (Inglaterra)","role":"filósofo, jurista y político","idea":"Saber es poder: la ciencia debe partir de la observación de la naturaleza y avanzar por inducción, libre de los prejuicios de la mente.","obras":["Novum organum","Ensayos","La nueva Atlántida"],"fuente":"John Aubrey, Vidas breves","tradicion":true,"block":"ren","subjects":["hf"],"temas":["hf-renacimiento-magia","hf-utopias-autoras","hf-racionalismo"]},"galileo":{"name":"Galileo Galilei","dates":"1564 – 1642","born":1564,"died":1642,"place":"Pisa (Italia)","role":"físico y astrónomo","idea":"La naturaleza está escrita en lenguaje matemático, y solo la experimentación controlada y la medición permiten conocer sus leyes, no la autoridad de Aristóteles.","obras":["El mensajero sideral (1610)","Diálogo sobre los dos máximos sistemas del mundo (1632)","Discursos y demostraciones matemáticas sobre dos nuevas ciencias (1638)"],"fuente":"Vincenzo Viviani, Relato histórico de la vida de Galileo","tradicion":true,"block":"ren","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-aa","hf-modernidad","hf-metafisica","hf-analitica","hf-descartes-makro"]},"campanella":{"name":"Tommaso Campanella","dates":"1568 – 1639","born":1568,"died":1639,"place":"Stilo (Calabria, Italia)","role":"fraile dominico, filósofo y escritor utópico","idea":"En una sociedad justa no habría propiedad privada: los bienes serían comunes y todos trabajarían unas pocas horas al día.","obras":["La ciudad del Sol (1602; publicada en 1623)","Apología de Galileo (1622)"],"fuente":"Actas del proceso de Nápoles (1601); biografías de Campanella basadas en ellas","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-renacimiento-magia","hf-utopias-autoras","hf-marx-biblioteca"]},"kepler":{"name":"Johannes Kepler","dates":"1571 – 1630","born":1571,"died":1630,"place":"Weil der Stadt (Alemania)","role":"astrónomo y matemático","idea":"Los planetas no giran en círculos perfectos, sino en órbitas elípticas con el Sol en uno de sus focos, siguiendo leyes matemáticas precisas.","obras":["El misterio cosmográfico (1596)","Astronomía nueva (1609)","La armonía del mundo (1619)"],"fuente":"Kepler, El secreto del universo (Mysterium cosmographicum), prefacio","tradicion":false,"block":"ren","subjects":["hf"],"temas":["hf-modernidad","hf-renacimiento-magia","hf-descartes-makro"]},"harvey":{"name":"William Harvey","dates":"1578 – 1657","born":1578,"died":1657,"place":"Folkestone (Inglaterra)","role":"médico y fisiólogo","idea":"La sangre circula continuamente por el cuerpo impulsada por el corazón, que actúa como una bomba, y así lo demuestran la observación y el experimento.","obras":["Sobre el movimiento del corazón y de la sangre en los animales (1628)"],"fuente":"John Aubrey, Vidas breves","tradicion":true,"block":"ren","subjects":["hf"],"temas":["hf-marxismos","hf-descartes-makro"]},"hobbes":{"name":"Thomas Hobbes","dates":"1588 – 1679","born":1588,"died":1679,"place":"Westport, Malmesbury (Inglaterra)","role":"filósofo y teórico político","idea":"Sin Estado, los seres humanos viven en una guerra de todos contra todos; por miedo a la muerte, pactan ceder todo su poder a un soberano absoluto.","obras":["Elementos de derecho natural y político (1640)","Sobre el ciudadano (1642)","Leviatán (1651)","Sobre el cuerpo (1655)"],"fuente":"John Aubrey, Vidas breves","tradicion":false,"block":"mod","subjects":["hf"],"temas":["hf-medieval","hf-racionalismo","hf-metafisica","hf-contrato","hf-utilitarismo"]},"descartes":{"name":"René Descartes","dates":"1596 – 1650","born":1596,"died":1650,"place":"La Haye (Turena, Francia)","role":"filósofo y matemático","idea":"Dudando metódicamente de todo, se alcanza una verdad indudable, pienso, luego existo, desde la que la razón reconstruye con certeza todo el conocimiento.","obras":["Reglas para la dirección del espíritu (h. 1628; publicada en 1701)","El mundo (1633; renunció a publicarlo tras la condena de Galileo)","Discurso del método, con la Dióptrica, los Meteoros y la Geometría (1637)","Meditaciones metafísicas (1641)","Los principios de la filosofía (1644)","Las pasiones del alma (1649)"],"fuente":"Descartes, Discurso del método II; Adrien Baillet, Vida de Descartes","tradicion":false,"vida":[{"a":1604,"b":1612,"t":"Estudia en el colegio jesuita de La Flèche"},{"a":1616,"t":"Se licencia en Derecho en Poitiers"},{"a":1618,"t":"Soldado voluntario en los Países Bajos; conoce a Beeckman"},{"a":1619,"t":"Los tres sueños del 10 de noviembre"},{"a":1628,"b":1649,"t":"Vive en los Países Bajos"},{"a":1633,"t":"Renuncia a publicar El mundo tras la condena de Galileo"},{"a":1637,"t":"Discurso del método"},{"a":1641,"t":"Meditaciones metafísicas"},{"a":1644,"t":"Los principios de la filosofía"},{"a":1649,"t":"Las pasiones del alma; viaja a Suecia invitado por la reina Cristina"}],"block":"ren","subjects":["hf"],"temas":["hf-euskal-herria","hf-filosofia-espanola","hf-metodos","hf-medieval","hf-platon-agustin","hf-fe-razon","hf-cinco-vias","hf-modernidad","hf-montaigne-ensayos","hf-renacimiento-magia","hf-racionalismo","hf-descartes-simulacion","hf-metafisica","hf-spinoza-sistema","hf-bayle-diccionario","hf-kant","hf-filosofas-dialogo","hf-capitalismo","hf-existencialismo","hf-descartes-makro"]},"gracian":{"name":"Baltasar Gracián","dates":"1601 – 1658","born":1601,"died":1658,"place":"Belmonte de Calatayud (Aragón)","role":"escritor y filósofo moralista jesuita","idea":"En un mundo lleno de apariencias y engaños, vivir bien exige agudeza, prudencia y el arte de conocer a las personas y a uno mismo.","obras":["El Héroe (1637)","Oráculo manual y arte de prudencia (1647)","Agudeza y arte de ingenio (1648)","El Criticón (1651–1657)"],"fuente":"Documentación interna de la Compañía de Jesús sobre las sanciones a Gracián tras publicar El Criticón sin licencia, recogida en las biografías modernas del autor","tradicion":false,"block":"mod","subjects":["hf"],"temas":["hf-filosofia-espanola"]},"isabel":{"name":"Isabel de Bohemia","dates":"1618 – 1680","born":1618,"died":1680,"place":"Heidelberg (Alemania)","role":"princesa y filósofa","idea":"Si el alma es inmaterial y el cuerpo es pura extensión, no se entiende cómo el alma puede mover el cuerpo: el dualismo cartesiano necesita una explicación.","obras":["Correspondencia con Descartes (1643–1649)"],"fuente":"Descartes, dedicatoria de los Principios de la filosofía (1644)","tradicion":false,"block":"mod","subjects":["hf"],"temas":["hf-filosofas-dialogo","hf-descartes-makro"]},"pascal":{"name":"Blaise Pascal","dates":"1623 – 1662","born":1623,"died":1662,"place":"Clermont (Auvernia, Francia)","role":"matemático, físico y filósofo","idea":"La razón es poderosa pero limitada: el ser humano es una caña pensante, frágil y grande a la vez, y «el corazón tiene razones que la razón no conoce».","obras":["Experiencias nuevas sobre el vacío (1647)","Las provinciales (1656-1657)","Pensamientos (póstumo, 1670)"],"fuente":"Memorial de Pascal (1654), conservado en la Biblioteca Nacional de Francia","tradicion":false,"block":"mod","subjects":["hf"],"temas":["hf-judios-andalus","hf-montaigne-ensayos"]},"spinoza":{"name":"Baruch Spinoza","dates":"1632 – 1677","born":1632,"died":1677,"place":"Ámsterdam (Países Bajos)","role":"filósofo racionalista","idea":"Solo existe una sustancia, Dios o la Naturaleza, y el pensamiento y la extensión son dos atributos suyos; la libertad consiste en comprender la necesidad.","obras":["Tratado teológico-político (1670)","Ética demostrada según el orden geométrico (1677)","Tratado de la reforma del entendimiento (1677)"],"fuente":"Leibniz, notas de su conversación con Spinoza (1676)","tradicion":false,"vida":[{"a":1677,"t":"Se publica la Ética, póstuma"}],"block":"mod","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-medieval","hf-judios-andalus","hf-montaigne-ensayos","hf-racionalismo","hf-metafisica","hf-spinoza-sistema","hf-spinoza-universal","hf-bayle-diccionario","hf-kant-poetas","hf-kant-juicios","hf-descartes-makro"]},"locke":{"name":"John Locke","dates":"1632 – 1704","born":1632,"died":1704,"place":"Wrington (Inglaterra)","role":"filósofo empirista y político","idea":"La mente nace como una hoja en blanco que llena la experiencia, y el poder político solo es legítimo si protege los derechos naturales de vida, libertad y propiedad.","obras":["Carta sobre la tolerancia (1689)","Ensayo sobre el entendimiento humano (1690)","Dos tratados sobre el gobierno civil (1690)"],"fuente":"Locke, «Epístola al lector» del Ensayo sobre el entendimiento humano","tradicion":false,"block":"mod","subjects":["hf"],"temas":["hf-aa","hf-medieval","hf-utopias-autoras","hf-racionalismo","hf-metafisica","hf-spinoza-universal","hf-contrato","hf-utilitarismo","hf-ilustracion","hf-descartes-makro"]},"malebranche":{"name":"Nicolas Malebranche","dates":"1638 – 1715","born":1638,"died":1715,"place":"París (Francia)","role":"filósofo y sacerdote racionalista","idea":"Las criaturas no causan nada por sí mismas: Dios es la única causa verdadera y actúa en cada ocasión para coordinar el alma y el cuerpo.","obras":["La búsqueda de la verdad (1674–1675)","Tratado de la naturaleza y de la gracia (1680)","Conversaciones sobre la metafísica y la religión (1688)"],"block":"mod","subjects":["hf"],"temas":["hf-islam-ideas","hf-racionalismo","hf-metafisica","hf-descartes-makro"]},"newton":{"name":"Isaac Newton","dates":"1642 – 1727","born":1642,"died":1727,"place":"Woolsthorpe (Inglaterra)","role":"físico y matemático","idea":"Una misma ley de gravitación universal explica tanto la caída de los cuerpos en la Tierra como el movimiento de los planetas, unificando la física terrestre y la celeste.","obras":["Principios matemáticos de la filosofía natural (1687)","Óptica (1704)"],"fuente":"William Stukeley, Memorias de la vida de Sir Isaac Newton","tradicion":true,"block":"mod","subjects":["hf"],"temas":["hf-beefs","hf-aa","hf-modernidad","hf-renacimiento-magia","hf-metafisica","hf-ilustracion","hf-kant","hf-marxismos","hf-analitica","hf-descartes-makro"]},"leibniz":{"name":"Gottfried Wilhelm Leibniz","dates":"1646 – 1716","born":1646,"died":1716,"place":"Leipzig (Alemania)","role":"filósofo y matemático racionalista","idea":"La realidad está formada por infinitas mónadas, sustancias simples que no interactúan, cuyo orden sincronizó Dios desde el principio en el mejor de los mundos posibles.","obras":["Discurso de metafísica (1686)","Nuevos ensayos sobre el entendimiento humano (escritos en 1704)","Teodicea (1710)","Monadología (1714)"],"fuente":"Notas autobiográficas de Leibniz","tradicion":false,"block":"mod","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-beefs","hf-cinco-vias","hf-racionalismo","hf-metafisica","hf-spinoza-universal","hf-bayle-diccionario","hf-kant","hf-kant-juicios","hf-descartes-makro"]},"bayle":{"name":"Pierre Bayle","dates":"1647 – 1706","born":1647,"died":1706,"place":"Le Carla (Francia)","role":"filósofo y erudito, precursor de la Ilustración","idea":"Defendió la tolerancia y la libertad de conciencia y sostuvo que una sociedad de ateos podría ser tan moral como una de creyentes; su Diccionario histórico y crítico convirtió la duda y la crítica de las fuentes en un método y fue una obra de referencia para la Ilustración.","obras":["Pensamientos diversos sobre el cometa (1682)","Comentario filosófico sobre las palabras «Oblígales a entrar» (1686)","Diccionario histórico y crítico (1697; 2.ª ed. 1702)","Noticias de la República de las Letras (revista, 1684–1687)"],"fuente":"Stanford Encyclopedia of Philosophy, «Pierre Bayle» (plato.stanford.edu/entries/bayle)","tradicion":false,"block":"mod","subjects":["hf"],"temas":["hf-spinoza-universal","hf-bayle-diccionario"]},"feijoo":{"name":"Benito Jerónimo Feijoo","dates":"1676 – 1764","born":1676,"died":1764,"place":"Casdemiro (Ourense, Galicia)","role":"monje benedictino y ensayista","idea":"Combatir con la experiencia y la razón los errores comunes, las supersticiones y los falsos milagros: no hay que creer algo porque lo diga todo el mundo o la costumbre, sino porque haya pruebas.","obras":["Teatro crítico universal (1726-1740)","Cartas eruditas y curiosas (1742-1760)","«Defensa de las mujeres» (en el Teatro crítico universal, tomo I, 1726)"],"fuente":"Real orden de Fernando VI de 1750; estudios sobre la polémica feijoniana (Centro de Estudios del Siglo XVIII, Universidad de Oviedo)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-filosofia-espanola"]},"berkeley":{"name":"George Berkeley","dates":"1685 – 1753","born":1685,"died":1753,"place":"Condado de Kilkenny (Irlanda)","role":"filósofo empirista y obispo","idea":"Ser es ser percibido: las cosas materiales no existen fuera de la mente, sino que son conjuntos de ideas percibidas, sostenidas en último término por Dios.","obras":["Ensayo sobre una nueva teoría de la visión (1709)","Tratado sobre los principios del conocimiento humano (1710)","Tres diálogos entre Hilas y Filonús (1713)"],"fuente":"James Boswell, Vida de Samuel Johnson","tradicion":false,"block":"mod","subjects":["hf"],"temas":["hf-racionalismo","hf-metafisica","hf-descartes-makro"]},"montesquieu":{"name":"Montesquieu","dates":"1689 – 1755","born":1689,"died":1755,"place":"La Brède, cerca de Burdeos (Francia)","role":"pensador político ilustrado","idea":"Para evitar el despotismo y garantizar la libertad, el poder debe dividirse en legislativo, ejecutivo y judicial, de modo que cada poder frene a los otros.","obras":["Cartas persas (1721)","Del espíritu de las leyes (1748)"],"block":"ilu","subjects":["hf"],"temas":["hf-contrato","hf-ilustracion","hf-sospecha"]},"voltaire":{"name":"Voltaire","dates":"1694 – 1778","born":1694,"died":1778,"place":"París (Francia)","role":"escritor y filósofo ilustrado","idea":"La razón debe combatir el fanatismo y la superstición; la tolerancia religiosa y la libertad de expresión son condiciones de una sociedad civilizada.","obras":["Cartas filosóficas (1734)","Cándido (1759)","Tratado sobre la tolerancia (1763)","Diccionario filosófico (1764)"],"fuente":"Biografías de Voltaire, a partir de testimonios de la época","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-beefs","hf-spinoza-universal","hf-ilustracion","hf-bayle-diccionario","hf-kant-juicios"]},"du_chatelet":{"name":"Émilie du Châtelet","dates":"1706 – 1749","born":1706,"died":1749,"place":"París (Francia)","role":"matemática, física y filósofa de la Ilustración","idea":"La física de Newton debe completarse con una reflexión filosófica sobre sus fundamentos; y el saber, también para las mujeres, es una de las fuentes de la felicidad.","obras":["Instituciones de física (1740)","Discurso sobre la felicidad (escrito hacia 1746-1747, publicado en 1779)","Principios matemáticos de la filosofía natural de Newton, traducción y comentario (publicada en 1759)"],"fuente":"Cartas de Émilie du Châtelet (1749); prefacio de Voltaire a la edición de 1759","tradicion":false,"block":"ilu","subjects":["hf"],"temas":[]},"euler":{"name":"Leonhard Euler","dates":"1707 – 1783","born":1707,"died":1783,"place":"Basilea (Suiza)","role":"matemático suizo","idea":"Las relaciones entre clases pueden verse como relaciones entre círculos: uno dentro de otro, separados o cruzados.","obras":["Introducción al análisis de los infinitos (1748)","Cartas a una princesa de Alemania (1768-1772)"],"fuente":"J. J. O'Connor y E. F. Robertson, «Leonhard Euler», MacTutor History of Mathematics","block":"ilu","subjects":["hf"],"temas":["hf-kant-juicios"]},"lamettrie":{"name":"Julien Offray de La Mettrie","dates":"1709 – 1751","born":1709,"died":1751,"place":"Saint-Malo (Francia)","role":"médico y filósofo materialista","idea":"El ser humano es una máquina compleja: el alma no es una sustancia espiritual, sino el resultado del funcionamiento de los órganos, sobre todo del cerebro.","obras":["Historia natural del alma (1745)","El hombre máquina (1748)"],"fuente":"Cartas de Voltaire desde Berlín; Federico II, Elogio de La Mettrie","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-metafisica"]},"mably":{"name":"Gabriel Bonnot de Mably","dates":"1709 – 1785","born":1709,"died":1785,"place":"Grenoble (Francia)","role":"abate, historiador y pensador político","idea":"La desigualdad de bienes es la fuente de los males sociales; la igualdad y la virtud de los ciudadanos valen más que la riqueza.","obras":["Dudas propuestas a los filósofos economistas sobre el orden natural y esencial de las sociedades políticas (1768)","De la legislación o principios de las leyes (1776)","De los derechos y deberes del ciudadano (escrita en 1758; publicada en 1789)"],"fuente":"Biografías de Mably de finales del siglo XVIII, recogidas en diccionarios biográficos posteriores (p. ej., el de Chalmers)","tradicion":true,"block":"ilu","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"hume":{"name":"David Hume","dates":"1711 – 1776","born":1711,"died":1776,"place":"Edimburgo (Escocia)","role":"filósofo empirista e historiador","idea":"Todo conocimiento procede de las impresiones de la experiencia; ideas como la causalidad o el yo sustancial no se justifican por la razón, sino por la costumbre.","obras":["Tratado de la naturaleza humana (1739-1740)","Investigación sobre el entendimiento humano (1748)","Investigación sobre los principios de la moral (1751)","Diálogos sobre la religión natural (1779)"],"fuente":"Tradición de Edimburgo, recogida en biografías de Hume (E. C. Mossner, The Life of David Hume)","tradicion":true,"vida":[{"a":1739,"b":1740,"t":"Tratado de la naturaleza humana"}],"block":"ilu","subjects":["hf"],"temas":["hf-beefs","hf-medieval","hf-fe-razon","hf-verdad-no-contradice","hf-cinco-vias","hf-modernidad","hf-montaigne-ensayos","hf-racionalismo","hf-metafisica","hf-spinoza-universal","hf-bayle-diccionario","hf-kant","hf-kant-juicios","hf-descartes-makro"]},"rousseau":{"name":"Jean-Jacques Rousseau","dates":"1712 – 1778","born":1712,"died":1778,"place":"Ginebra (Suiza)","role":"filósofo y teórico político","idea":"El ser humano es bueno por naturaleza y la sociedad lo corrompe; un contrato social legítimo exige obedecer a la voluntad general, expresión de la soberanía popular.","obras":["Discurso sobre el origen de la desigualdad (1755)","El contrato social (1762)","Emilio, o De la educación (1762)"],"fuente":"Rousseau, Confesiones, libro VIII; Segunda carta a Malesherbes (1762)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-beefs","hf-medieval","hf-montaigne-ensayos","hf-contrato","hf-ilustracion","hf-kant"]},"diderot":{"name":"Denis Diderot","dates":"1713 – 1784","born":1713,"died":1784,"place":"Langres (Francia)","role":"filósofo y escritor ilustrado","idea":"El saber debe reunirse, ordenarse y difundirse para liberar a las personas de la ignorancia y los prejuicios, al servicio del progreso social.","obras":["Carta sobre los ciegos (1749)","Enciclopedia (1751-1772)","El sobrino de Rameau","Jacques el fatalista"],"fuente":"Correspondencia de Diderot; testimonios de la época (Grimm, Correspondance littéraire)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-ilustracion","hf-bayle-diccionario","hf-marx-biblioteca"]},"helvetius":{"name":"Claude-Adrien Helvétius","dates":"1715 – 1771","born":1715,"died":1771,"place":"París (Francia)","role":"filósofo materialista de la Ilustración","idea":"Las diferencias entre las personas se deben a la educación y al ambiente; el interés guía la conducta, y las buenas leyes hacen que el interés de cada uno coincida con el de todos.","obras":["Del espíritu","Del hombre"],"block":"ilu","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"dalembert":{"name":"Jean le Rond d'Alembert","dates":"1717 – 1783","born":1717,"died":1783,"place":"París","role":"matemático y filósofo ilustrado","idea":"El conocimiento humano puede ordenarse de forma sistemática a partir de la experiencia y la razón, y la ciencia es el modelo del saber que impulsa el progreso.","obras":["Tratado de dinámica (1743)","Discurso preliminar de la Enciclopedia (1751)"],"fuente":"Condorcet, Elogio de D'Alembert; tradición biográfica","tradicion":true,"block":"ilu","subjects":["hf"],"temas":["hf-ilustracion","hf-bayle-diccionario"]},"morelly":{"name":"Étienne-Gabriel Morelly","dates":"c. 1717 – c. 1778","born":1717,"died":1778,"place":"Francia (probablemente París)","role":"escritor y pensador comunista de la Ilustración","idea":"La propiedad privada es la raíz de todos los vicios; en una sociedad conforme a la naturaleza, nada pertenecería a nadie en particular.","obras":["Naufragio de las islas flotantes o Basilíada (1753)","Código de la naturaleza (1755)"],"fuente":"Defensa de Babeuf ante el tribunal de Vendôme (1797); Antoine-Alexandre Barbier, Diccionario de obras anónimas","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"holbach":{"name":"Barón d'Holbach","dates":"1723 – 1789","born":1723,"died":1789,"place":"Edesheim (Palatinado, Alemania)","role":"filósofo materialista y enciclopedista","idea":"Solo existe la materia en movimiento; el ser humano es parte de la naturaleza, y la religión nace del miedo y de la ignorancia.","obras":["Sistema de la naturaleza","El cristianismo desvelado"],"block":"ilu","subjects":["hf"],"temas":["hf-metafisica","hf-marx-biblioteca"]},"smith":{"name":"Adam Smith","dates":"1723 – 1790","born":1723,"died":1790,"place":"Kirkcaldy (Escocia)","role":"filósofo moral y economista","idea":"Al buscar cada uno su propio interés en un mercado libre, los individuos contribuyen sin pretenderlo al bienestar general, como guiados por una mano invisible.","obras":["Teoría de los sentimientos morales (1759)","La riqueza de las naciones (1776)"],"fuente":"Dugald Stewart, Account of the Life and Writings of Adam Smith (sobre sus despistes); anécdotas de la tradición escocesa","tradicion":true,"block":"ilu","subjects":["hf"],"temas":["hf-utilitarismo"]},"kant":{"name":"Immanuel Kant","dates":"1724 – 1804","born":1724,"died":1804,"place":"Königsberg (Prusia)","role":"filósofo ilustrado alemán","idea":"Solo conocemos los fenómenos ordenados por las formas a priori del sujeto; y la moral se funda en el deber que la razón autónoma se da a sí misma.","obras":["Crítica de la razón pura (1781)","Fundamentación de la metafísica de las costumbres (1785)","Crítica de la razón práctica (1788)","Crítica del juicio (1790)"],"fuente":"Tradición biográfica; sobre sus costumbres, biografías de Borowski, Jachmann y Wasianski","tradicion":true,"block":"ilu","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-metodos","hf-beefs","hf-cinco-vias","hf-montaigne-ensayos","hf-racionalismo","hf-metafisica","hf-spinoza-sistema","hf-spinoza-universal","hf-ilustracion","hf-kant","hf-kant-poetas","hf-kant-juicios","hf-etica-deber","hf-sospecha","hf-filosofas-dialogo","hf-descartes-makro"]},"lessing":{"name":"Gotthold Ephraim Lessing","dates":"1729 – 1781","born":1729,"died":1781,"place":"Kamenz (Alemania)","role":"dramaturgo, crítico y filósofo ilustrado","idea":"Ninguna religión puede demostrar que posee toda la verdad; su valor se ve en la conducta de quienes la practican, sobre todo en la tolerancia.","obras":["Laocoonte (1766)","Minna von Barnhelm (1767)","Natán el sabio (1779)","La educación del género humano (1780)"],"fuente":"Carta de Lessing a Elise Reimarus (6 de septiembre de 1778)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-spinoza-universal","hf-kant-poetas"]},"mendelssohn":{"name":"Moses Mendelssohn","dates":"1729 – 1786","born":1729,"died":1786,"place":"Dessau (Alemania)","role":"filósofo de la Ilustración judía","idea":"La razón puede demostrar la existencia de Dios y la inmortalidad del alma, y el Estado no debe obligar a nadie en materia de creencias.","obras":["Conversaciones filosóficas (1755)","Fedón (1767)","Jerusalén (1783)","Horas matinales (1785)"],"fuente":"Concurso de la Academia de Ciencias de Berlín (1763) y correspondencia entre Kant y Mendelssohn","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-spinoza-universal","hf-kant-poetas"]},"hamann":{"name":"Johann Georg Hamann","dates":"1730 – 1788","born":1730,"died":1788,"place":"Königsberg (hoy Kaliningrado, Rusia)","role":"pensador religioso, el «Mago del Norte»","idea":"No hay razón pura separada del lenguaje, la tradición y la historia: pensamos siempre con palabras heredadas.","obras":["Memorables socráticos (1759)","Cruzadas del filólogo (1762)","Gólgota y Scheblimini (1784)","Metacrítica sobre el purismo de la razón (1784)"],"fuente":"Hamann, Pensamientos sobre el curso de mi vida (1758)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-kant-poetas","hf-sospecha"]},"jefferson":{"name":"Thomas Jefferson","dates":"1743 – 1826","born":1743,"died":1826,"place":"Shadwell, Virginia (colonias británicas de América)","role":"político ilustrado estadounidense, autor de la Declaración de Independencia","idea":"Todos los seres humanos tienen derechos naturales, como la vida, la libertad y la búsqueda de la felicidad; los gobiernos existen para protegerlos, obtienen su poder del consentimiento de los gobernados y deben separarse de la religión.","obras":["Declaración de Independencia (1776)","Notas sobre el estado de Virginia (1785)","Estatuto de Virginia para la libertad religiosa (1786)","La vida y la moral de Jesús de Nazaret (1820)"],"fuente":"Carta de Jefferson a John Adams (12-10-1813); ejemplar original en el Instituto Smithsonian (Washington)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-metafisica"]},"jacobi":{"name":"Friedrich Heinrich Jacobi","dates":"1743 – 1819","born":1743,"died":1819,"place":"Düsseldorf (Alemania)","role":"filósofo y novelista, crítico de la Ilustración","idea":"La razón, llevada hasta el final, desemboca en Spinoza y en la negación de la libertad; solo un salto de la fe nos da a Dios y a la persona libre.","obras":["Woldemar (1779)","Sobre la doctrina de Spinoza, en cartas al señor Moses Mendelssohn (1785)","David Hume sobre la fe, o idealismo y realismo (1787)","Carta a Fichte (1799)"],"fuente":"Goethe, Poesía y verdad, libro XIV","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-spinoza-universal","hf-kant-poetas"]},"paley":{"name":"William Paley","dates":"1743 – 1805","born":1743,"died":1805,"place":"Peterborough (Inglaterra)","role":"clérigo y filósofo inglés","idea":"Si al encontrar un reloj deducimos que alguien lo hizo, el ojo y los demás órganos de los seres vivos, mucho más complejos, exigen un diseñador inteligente.","obras":["Principios de filosofía moral y política (1785)","Una visión de las pruebas del cristianismo (1794)","Teología natural (1802)"],"fuente":"Carta de Charles Darwin a John Lubbock, 22 de noviembre de 1859 (Darwin Correspondence Project)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-cinco-vias"]},"condorcet":{"name":"Nicolas de Condorcet","dates":"1743 – 1794","born":1743,"died":1794,"place":"Ribemont (Picardía, Francia)","role":"matemático, filósofo ilustrado y político de la Revolución francesa","idea":"La humanidad puede progresar sin un límite fijado de antemano gracias a la razón, la ciencia y la educación, y ese progreso exige los mismos derechos para todos: también para las mujeres y para los esclavos.","obras":["Reflexiones sobre la esclavitud de los negros (1781)","Ensayo sobre la aplicación del análisis a la probabilidad de las decisiones tomadas por mayoría (1785)","Sobre la admisión de las mujeres al derecho de ciudadanía (1790)","Cinco memorias sobre la instrucción pública (1791)","Esbozo de un cuadro histórico de los progresos del espíritu humano (1795, póstumo)"],"fuente":"Relato tradicional repetido por sus biógrafos desde el siglo XIX; los detalles de la detención no están documentados con seguridad","tradicion":true,"block":"ilu","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-ilustracion"]},"herder":{"name":"Johann Gottfried Herder","dates":"1744 – 1803","born":1744,"died":1803,"place":"Mohrungen (hoy Morąg, Polonia)","role":"filósofo del lenguaje y de la historia","idea":"Cada pueblo y cada época tienen su propia lengua, su propia cultura y su propio valor; la historia no es una escalera que lleva a la Europa ilustrada.","obras":["Tratado sobre el origen del lenguaje (1772)","Otra filosofía de la historia (1774)","Ideas para la filosofía de la historia de la humanidad (1784-1791)","Dios. Algunas conversaciones (1787)"],"fuente":"Herder, Diario de mi viaje en el año 1769","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-spinoza-universal","hf-kant-poetas","hf-sospecha"]},"jovellanos":{"name":"Gaspar Melchor de Jovellanos","dates":"1744 – 1811","born":1744,"died":1811,"place":"Gijón (Asturias)","role":"ilustrado, jurista, político y escritor","idea":"El progreso de un país depende sobre todo de la educación y de quitar las trabas que ahogan la economía: la instrucción pública es el primer origen de la prosperidad social.","obras":["Informe sobre la Ley Agraria (1795)","Memoria sobre educación pública (1802)","Memoria sobre espectáculos y diversiones públicas (1790)","Diarios"],"fuente":"Diarios de Jovellanos; biografías de referencia (Real Academia de la Historia, «Gaspar Melchor de Jovellanos»; Biblioteca Virtual Miguel de Cervantes)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-filosofia-espanola"]},"bentham":{"name":"Jeremy Bentham","dates":"1748 – 1832","born":1748,"died":1832,"place":"Londres","role":"filósofo y jurista utilitarista","idea":"Una acción es buena si aumenta el placer y reduce el dolor de los afectados; la moral y las leyes deben buscar la mayor felicidad para el mayor número.","obras":["Fragmento sobre el gobierno (1776)","Introducción a los principios de la moral y la legislación (1789)","Panóptico (1791)"],"fuente":"Testamento de Bentham; University College London","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-utilitarismo","hf-etica-deber","hf-marx-biblioteca","hf-corazon-piedra","hf-posmodernidad"]},"gouges":{"name":"Olympe de Gouges","dates":"1748 – 1793","born":1748,"died":1793,"place":"Montauban (Francia)","role":"escritora y activista política","idea":"Los derechos proclamados por la Revolución francesa deben valer también para las mujeres, que son ciudadanas con los mismos derechos que los hombres.","obras":["Declaración de los derechos de la mujer y de la ciudadana (1791)"],"fuente":"Carta de Olympe de Gouges a la Convención (diciembre de 1792)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-utopias-autoras","hf-ilustracion","hf-filosofas-dialogo"]},"goethe":{"name":"Johann Wolfgang von Goethe","dates":"1749 – 1832","born":1749,"died":1832,"place":"Fráncfort del Meno (Alemania)","role":"poeta, novelista, naturalista y ministro","idea":"Lo universal no se alcanza alejándose de las cosas, sino mirándolas con atención: en lo particular, bien observado, se ve la ley.","obras":["Las penas del joven Werther (1774)","La metamorfosis de las plantas (1790)","Los años de aprendizaje de Wilhelm Meister (1795-1796)","Fausto (1808 y 1832)"],"fuente":"Carta de Goethe a Herder (27 de marzo de 1784)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-renacimiento-magia","hf-spinoza-sistema","hf-spinoza-universal","hf-kant-poetas","hf-corazon-piedra"]},"roux":{"name":"Jacques Roux","dates":"1752 – 1794","born":1752,"died":1794,"place":"Pranzac (Francia)","role":"sacerdote y revolucionario «enragé»","idea":"La libertad es una ilusión si una clase de personas puede matar de hambre a otra; hay que castigar a los acaparadores y fijar los precios.","obras":["Manifiesto de los enragés (1793)","El publicista de la República francesa (periódico, 1793)"],"fuente":"Informe de Jacques Roux al Consejo general de la Comuna de París (21 de enero de 1793)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"hamilton":{"name":"Alexander Hamilton","dates":"c. 1755 – 1804","born":1755,"died":1804,"place":"Nevis (Antillas británicas)","role":"político y pensador político estadounidense","idea":"La libertad se protege mejor con un gobierno fuerte y bien equilibrado, en el que los poderes separados se vigilan unos a otros.","obras":["El Federalista (con Madison y Jay)"],"block":"ilu","subjects":["hf"],"temas":[]},"godwin":{"name":"William Godwin","dates":"1756 – 1836","born":1756,"died":1836,"place":"Wisbech (Inglaterra)","role":"filósofo político y novelista","idea":"Los gobiernos y la propiedad acumulada corrompen a las personas; una sociedad guiada por la razón podría vivir sin Estado y repartir los bienes según las necesidades.","obras":["Investigación sobre la justicia política (1793)","Caleb Williams (1794)","Memorias de la autora de «Vindicación de los derechos de la mujer» (1798)"],"fuente":"Cartas entre Godwin y Wollstonecraft (1796-1797); Godwin, Memorias de la autora de «Vindicación de los derechos de la mujer» (1798)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-marx-biblioteca","hf-corazon-piedra"]},"hebert":{"name":"Jacques-René Hébert","dates":"1757 – 1794","born":1757,"died":1794,"place":"Alençon (Francia)","role":"periodista y político revolucionario","idea":"La Revolución debe hablar el lenguaje del pueblo llano y castigar sin piedad a sus enemigos.","obras":["El Padre Duchesne (periódico, 1790-1794)"],"fuente":"Relatos contemporáneos de la ejecución de los hebertistas (marzo de 1794)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"wollstonecraft":{"name":"Mary Wollstonecraft","dates":"1759 – 1797","born":1759,"died":1797,"place":"Londres","role":"filósofa y escritora","idea":"La supuesta inferioridad intelectual de las mujeres no es natural, sino fruto de su educación; con la misma formación, desarrollarían la misma razón que los hombres.","obras":["Pensamientos sobre la educación de las hijas (1787)","Vindicación de los derechos del hombre (1790)","Vindicación de los derechos de la mujer (1792)"],"fuente":"Wollstonecraft, Cartas escritas en Suecia, Noruega y Dinamarca; William Godwin, Memorias de la autora de «Vindicación de los derechos de la mujer»","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-beefs","hf-utopias-autoras","hf-ilustracion","hf-marx-biblioteca","hf-filosofas-dialogo","hf-corazon-piedra"]},"schiller":{"name":"Friedrich Schiller","dates":"1759 – 1805","born":1759,"died":1805,"place":"Marbach am Neckar (Alemania)","role":"dramaturgo, poeta e historiador","idea":"El ser humano solo es plenamente libre cuando razón y sensibilidad dejan de luchar, y la belleza es el camino para educarlo en esa armonía.","obras":["Los bandidos (1781)","Sobre la gracia y la dignidad (1793)","Cartas sobre la educación estética del hombre (1795)","Guillermo Tell (1804)"],"fuente":"Decreto de la Asamblea Legislativa francesa (26 de agosto de 1792); el diploma llegó a Weimar en marzo de 1798","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-kant-poetas","hf-corazon-piedra"]},"babeuf":{"name":"François-Noël Babeuf","dates":"1760 – 1797","born":1760,"died":1797,"place":"Saint-Quentin (Francia)","role":"periodista y revolucionario","idea":"La Revolución no estará terminada mientras no haya igualdad real: la tierra y sus frutos deben ser de todos.","obras":["El tribuno del pueblo (periódico, 1794-1796)"],"fuente":"Filippo Buonarroti, Conspiración por la igualdad llamada de Babeuf (1828); actas del proceso de Vendôme","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"saint-simon":{"name":"Henri de Saint-Simon","dates":"1760 – 1825","born":1760,"died":1825,"place":"París","role":"pensador social y reformador","idea":"La sociedad moderna debe estar dirigida por quienes producen, científicos, industriales y trabajadores, y organizarse para mejorar la vida de la clase más pobre.","obras":["Cartas de un habitante de Ginebra a sus contemporáneos (1803)","El organizador (1819-1820)","Catecismo de los industriales (1823-1824)","Nuevo cristianismo (1825)"],"fuente":"Saint-Simon, El organizador (1819); proceso ante el tribunal de lo criminal (1820)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"buonarroti":{"name":"Filippo Buonarroti","dates":"1761 – 1837","born":1761,"died":1837,"place":"Pisa (Italia)","role":"revolucionario y escritor","idea":"La igualdad perfecta, con los bienes en común, es la meta de la revolución; para alcanzarla hace falta una minoría organizada y decidida.","obras":["Conspiración por la igualdad llamada de Babeuf (1828)"],"fuente":"Estudios históricos sobre Buonarroti (Elizabeth Eisenstein, The First Professional Revolutionist, 1959); testimonio de Bakunin","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"fichte":{"name":"Johann Gottlieb Fichte","dates":"1762 – 1814","born":1762,"died":1814,"place":"Rammenau (Alemania)","role":"filósofo idealista","idea":"Todo parte de la actividad del yo, que se pone a sí mismo y pone frente a sí el mundo como el obstáculo en el que ejerce su libertad.","obras":["Ensayo de una crítica de toda revelación (1792)","Fundamento de toda la doctrina de la ciencia (1794-1795)","El destino del hombre (1800)","Discursos a la nación alemana (1808)"],"fuente":"Correspondencia de Fichte y Kant (1791); declaración de Kant en la Allgemeine Literatur-Zeitung de Jena (1792)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-kant-poetas"]},"malthus":{"name":"Thomas Robert Malthus","dates":"1766 – 1834","born":1766,"died":1834,"place":"Surrey (Inglaterra)","role":"clérigo y economista inglés","idea":"Si nada la frena, la población crece mucho más deprisa que los alimentos; por eso el hambre, la enfermedad y la miseria actúan como freno, salvo que las personas limiten los nacimientos.","obras":["Ensayo sobre el principio de la población (1798; edición ampliada, 1803)","Principios de economía política (1820)"],"fuente":"Charles Darwin, Autobiografía (1887)","tradicion":false,"block":"ilu","subjects":["hf"],"temas":[]},"schleiermacher":{"name":"Friedrich Schleiermacher","dates":"1768 – 1834","born":1768,"died":1834,"place":"Breslau (hoy Wrocław, Polonia)","role":"teólogo, filósofo y traductor","idea":"La religión no es una forma de saber ni una moral, sino el sentimiento y la intuición de lo infinito en lo finito.","obras":["Discursos sobre la religión a sus menospreciadores cultivados (1799)","Monólogos (1800)","La fe cristiana (1821-1822)"],"fuente":"Cartas de Schleiermacher a su hermana Charlotte (1797-1798)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-spinoza-universal"]},"hegel":{"name":"Georg Wilhelm Friedrich Hegel","dates":"1770 – 1831","born":1770,"died":1831,"place":"Stuttgart (Alemania)","role":"filósofo idealista alemán","idea":"La realidad es un proceso dialéctico en el que el Espíritu se desarrolla a través de la historia; cada filosofía es su propia época expresada en pensamientos.","obras":["Fenomenología del espíritu (1807)","Ciencia de la lógica (1812-1816)","Enciclopedia de las ciencias filosóficas (1817)","Fundamentos de la filosofía del derecho (1821)"],"fuente":"Carta de Hegel a Niethammer, 13 de octubre de 1806","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-historicidad","hf-metodos","hf-beefs","hf-mito","hf-montaigne-ensayos","hf-renacimiento-magia","hf-spinoza-sistema","hf-spinoza-universal","hf-kant-poetas","hf-kant-juicios","hf-sospecha","hf-corazon-piedra","hf-capitalismo","hf-posmodernidad","hf-beauvoir"]},"holderlin":{"name":"Friedrich Hölderlin","dates":"1770 – 1843","born":1770,"died":1843,"place":"Lauffen am Neckar (Alemania)","role":"poeta","idea":"El ser humano ha perdido la unidad con la naturaleza que vivieron los griegos, y la poesía puede ayudar a recuperarla.","obras":["Hiperión o el eremita en Grecia (1797-1799)","La muerte de Empédocles (1797-1800, inacabada)","Traducciones de Edipo rey y Antígona de Sófocles (1804)"],"fuente":"Testimonios de Ernst Zimmer y de Wilhelm Waiblinger; manuscritos de los poemas de la torre","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-spinoza-universal","hf-kant-poetas"]},"leclerc":{"name":"Théophile Leclerc","dates":"1771 – 1820","born":1771,"died":1820,"place":"Lézigneux (Francia)","role":"periodista revolucionario «enragé»","idea":"La Revolución debe seguir adelante en favor de los pobres, sin detenerse en compromisos con los ricos.","obras":["El amigo del pueblo, por Leclerc (periódico, 1793)"],"fuente":"Documentos policiales y judiciales de 1794; declaración de Pauline Léon en prisión","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"owen":{"name":"Robert Owen","dates":"1771 – 1858","born":1771,"died":1858,"place":"Newtown (Gales)","role":"empresario y reformador socialista","idea":"El carácter de las personas lo forman las circunstancias en que viven; si se mejoran esas circunstancias, con educación y trabajo digno, mejoran las personas.","obras":["Una nueva visión de la sociedad (1813)","Informe al condado de Lanark (1821)","El libro del nuevo mundo moral (1836-1844)","Vida de Robert Owen (1857)"],"fuente":"Robert Owen, Vida de Robert Owen escrita por él mismo (1857)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"fourier":{"name":"Charles Fourier","dates":"1772 – 1837","born":1772,"died":1837,"place":"Besanzón (Francia)","role":"pensador socialista utópico","idea":"El trabajo puede ser agradable si la sociedad se organiza de acuerdo con las pasiones humanas, en comunidades libres llamadas falansterios.","obras":["Teoría de los cuatro movimientos (1808)","Tratado de la asociación doméstica-agrícola (1822)","El nuevo mundo industrial y societario (1829)","La falsa industria (1835)"],"fuente":"Manuscritos de Fourier, publicados por su escuela tras su muerte","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-utopias-autoras","hf-marx-biblioteca"]},"novalis":{"name":"Novalis","dates":"1772 – 1801","born":1772,"died":1801,"place":"Oberwiederstedt (Alemania)","role":"poeta y pensador del primer Romanticismo","idea":"El mundo tiene que ser romantizado: hay que devolver a lo ordinario su misterio y descubrir lo infinito en lo finito.","obras":["Polen (1798)","Himnos a la noche (1800)","La cristiandad o Europa (1799, publicada en 1826)","Enrique de Ofterdingen (1802, póstuma)"],"fuente":"Diario de Novalis (1797)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-spinoza-universal","hf-kant-poetas"]},"schlegel":{"name":"Friedrich Schlegel","dates":"1772 – 1829","born":1772,"died":1829,"place":"Hannover (Alemania)","role":"crítico, filósofo y teórico del Romanticismo","idea":"La poesía romántica es una poesía universal progresiva: une todos los géneros, une poesía y filosofía, y nunca está acabada.","obras":["Ensayo sobre el concepto de republicanismo (1796)","Lucinde (1799)","Conversación sobre la poesía (1800)","Sobre la lengua y la sabiduría de los indios (1808)"],"fuente":"Schleiermacher, Cartas confidenciales sobre la Lucinde de Schlegel (1800); correspondencia del grupo de Jena","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-kant-poetas"]},"laborde":{"name":"Alexandre de Laborde","dates":"1773 – 1842","born":1773,"died":1842,"place":"París","role":"arqueólogo, viajero y político liberal","idea":"La asociación libre de las personas y de sus capitales es la mejor manera de mejorar la vida de toda la comunidad.","obras":["Viaje pintoresco e histórico por España (1807-1818)","Itinerario descriptivo de España (1809)","Del espíritu de asociación en todos los intereses de la comunidad (1818)"],"fuente":"Crónicas de las jornadas de julio de 1830; Archives parlementaires","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"thompson":{"name":"William Thompson","dates":"1775 – 1833","born":1775,"died":1833,"place":"Cork (Irlanda)","role":"economista y pensador socialista irlandés","idea":"Quien trabaja tiene derecho a todo lo que produce; la riqueza que se quedan los propietarios sin trabajar es una injusticia.","obras":["Investigación sobre los principios de la distribución de la riqueza (1824)","Llamamiento de una mitad de la raza humana, las mujeres, contra las pretensiones de la otra mitad, los hombres (1825)","El trabajo recompensado (1827)"],"fuente":"Testamento de Thompson y pleito posterior; prensa local de Cork","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marx-biblioteca","hf-marxismos"]},"schelling":{"name":"Friedrich Wilhelm Joseph Schelling","dates":"1775 – 1854","born":1775,"died":1854,"place":"Leonberg (Alemania)","role":"filósofo idealista","idea":"La naturaleza y el espíritu son dos caras de una misma realidad absoluta: la naturaleza es espíritu que aún no se sabe a sí mismo.","obras":["Ideas para una filosofía de la naturaleza (1797)","Sistema del idealismo trascendental (1800)","Investigaciones filosóficas sobre la esencia de la libertad humana (1809)"],"fuente":"Cartas y diarios de Søren Kierkegaard (1841-1842)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-renacimiento-magia","hf-spinoza-universal","hf-kant-poetas"]},"lamennais":{"name":"Félicité de Lamennais","dates":"1782 – 1854","born":1782,"died":1854,"place":"Saint-Malo (Francia)","role":"sacerdote y escritor político","idea":"El Evangelio exige libertad y justicia para el pueblo; la Iglesia debe separarse del poder de los reyes y ponerse del lado de los pobres.","obras":["Ensayo sobre la indiferencia en materia de religión (1817-1823)","Palabras de un creyente (1834)","El libro del pueblo (1837)"],"fuente":"Testamento de Lamennais; crónicas de su entierro (1 de marzo de 1854)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"cabet":{"name":"Étienne Cabet","dates":"1788 – 1856","born":1788,"died":1856,"place":"Dijon (Francia)","role":"abogado y político comunista","idea":"La injusticia nace de la propiedad privada; una comunidad de bienes, alcanzada de forma pacífica, traería la igualdad y la fraternidad.","obras":["Viaje por Icaria (1840)","El verdadero cristianismo según Jesucristo (1846)"],"fuente":"Historia de la colonia icariana; prensa icariana (El Popular)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"schopenhauer":{"name":"Arthur Schopenhauer","dates":"1788 – 1860","born":1788,"died":1860,"place":"Danzig (hoy Gdansk, Polonia)","role":"filósofo alemán del pesimismo","idea":"Detrás de todo lo que existe hay una voluntad ciega que nunca se sacia; por eso la vida es sobre todo dolor, y solo el arte, la compasión y la renuncia nos liberan un poco.","obras":["El mundo como voluntad y representación (1819; ampliada en 1844)","Los dos problemas fundamentales de la ética (1841)","Parerga y paralipómena (1851)"],"fuente":"R. Safranski, Schopenhauer y los años salvajes de la filosofía (1987)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-euskal-herria","hf-filosofia-espanola","hf-beefs","hf-sospecha"]},"heine":{"name":"Heinrich Heine","dates":"1797 – 1856","born":1797,"died":1856,"place":"Düsseldorf (Alemania)","role":"poeta y periodista","idea":"La filosofía alemana, de Kant a Hegel, fue una revolución en el pensamiento tan profunda como la Revolución francesa en la política.","obras":["Libro de los cantares (1827)","Historia de la religión y la filosofía en Alemania (1834)","Alemania. Un cuento de invierno (1844)","Romancero (1851)"],"fuente":"Heine, epílogo del Romancero (1851)","tradicion":true,"block":"con","subjects":["hf"],"temas":["hf-spinoza-universal","hf-corazon-piedra"]},"comte":{"name":"Auguste Comte","dates":"1798 – 1857","born":1798,"died":1857,"place":"Montpellier (Francia)","role":"filósofo positivista y sociólogo","idea":"El único conocimiento válido es el positivo, basado en hechos observables y leyes científicas; la humanidad progresa del estadio teológico al metafísico y al positivo.","obras":["Curso de filosofía positiva (1830-1842)","Discurso sobre el espíritu positivo (1844)","Sistema de política positiva (1851-1854)"],"fuente":"Testimonios del propio Comte y de sus discípulos","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-modernidad","hf-etica-deber","hf-sospecha"]},"balzac":{"name":"Honoré de Balzac","dates":"1799 – 1850","born":1799,"died":1850,"place":"Tours (Francia)","role":"novelista","idea":"La novela puede retratar una sociedad entera, y en la sociedad moderna lo que mueve a casi todos los personajes es el dinero.","obras":["La piel de zapa (1831)","Eugenia Grandet (1833)","Papá Goriot (1835)","Las ilusiones perdidas (1837-1843)"],"fuente":"Contrato de alquiler (1840) y carta de Balzac a Ewelina Hańska (16 de noviembre de 1840); Maison de Balzac (París)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-kant-poetas","hf-corazon-piedra"]},"feuerbach":{"name":"Ludwig Feuerbach","dates":"1804 – 1872","born":1804,"died":1872,"place":"Landshut (Baviera)","role":"filósofo materialista alemán","idea":"Dios no es más que la proyección de las cualidades humanas idealizadas; al adorarlo, el ser humano se aliena y se separa de su propia esencia.","obras":["La esencia del cristianismo (1841)","Tesis provisionales para la reforma de la filosofía (1842)","Principios de la filosofía del futuro (1843)"],"fuente":"Feuerbach, reseña de la obra de Moleschott sobre la alimentación (1850)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-sospecha","hf-marx-biblioteca","hf-capitalismo"]},"mill":{"name":"John Stuart Mill","dates":"1806 – 1873","born":1806,"died":1873,"place":"Londres","role":"filósofo y economista británico","idea":"Es correcta la acción que promueve la mayor felicidad del mayor número, pero los placeres intelectuales y morales valen más que los puramente físicos.","obras":["Sistema de lógica (1843)","Sobre la libertad (1859)","El utilitarismo (1863)","El sometimiento de la mujer (1869)"],"fuente":"John Stuart Mill, Autobiografía","tradicion":false,"block":"ilu","subjects":["hf"],"temas":["hf-comunidades-perseguidos","hf-utilitarismo","hf-etica-deber","hf-sospecha"]},"gay":{"name":"Jules Gay","dates":"1807 – 1887","born":1807,"died":1887,"place":"París","role":"editor y propagandista comunista","idea":"La comunidad de bienes que proponía Robert Owen es el camino para alcanzar la igualdad social y la igualdad entre hombres y mujeres.","obras":["Proposiciones fundamentales del sistema social de la comunidad de bienes (traducción de Owen, 1837)","El socialismo racional y el socialismo autoritario (1868)"],"fuente":"Biografías de Jules y Désirée Gay (Diccionario biográfico del movimiento obrero francés)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"considerant":{"name":"Victor Considerant","dates":"1808 – 1893","born":1808,"died":1893,"place":"Salins (Francia)","role":"ingeniero y político socialista fourierista","idea":"La sociedad puede transformarse de forma pacífica asociando el capital, el trabajo y el talento, sin necesidad de una revolución violenta.","obras":["Destino social (1834)","Principios del socialismo. Manifiesto de la democracia en el siglo XIX (1847)","En Texas (1855)"],"fuente":"Considerant, En Texas; historia de la colonia de La Reunión (Dallas)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"dezamy":{"name":"Théodore Dézamy","dates":"1808 – 1850","born":1808,"died":1850,"place":"Luçon (Francia)","role":"maestro y teórico comunista","idea":"El comunismo debe basarse en la razón y en el materialismo, no en la religión: una comunidad de bienes bien organizada haría inútiles los vicios y los delitos.","obras":["El señor Lamennais refutado por sí mismo (1841)","Código de la comunidad (1842)","Organización de la libertad y del bienestar universal (1846)"],"fuente":"Crónicas del banquete comunista de Belleville (1840)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marx-biblioteca"]},"darwin":{"name":"Charles Darwin","dates":"1809 – 1882","born":1809,"died":1882,"place":"Shrewsbury (Inglaterra)","role":"naturalista británico","idea":"Todas las especies descienden de antepasados comunes y se transforman lentamente por selección natural, que favorece a los individuos mejor adaptados a su medio.","obras":["El viaje del Beagle (1839)","El origen de las especies (1859)","El origen del hombre (1871)"],"fuente":"Charles Darwin, Autobiografía","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-cinco-vias","hf-sospecha"]},"proudhon":{"name":"Pierre-Joseph Proudhon","dates":"1809 – 1865","born":1809,"died":1865,"place":"Besanzón (Francia)","role":"pensador socialista y anarquista","idea":"La propiedad que permite vivir del trabajo ajeno es un robo; la sociedad justa se basa en acuerdos libres entre productores, sin un Estado que los domine.","obras":["¿Qué es la propiedad? (1840)","Sistema de las contradicciones económicas o Filosofía de la miseria (1846)","Idea general de la revolución en el siglo XIX (1851)","De la capacidad política de las clases obreras (1865)"],"fuente":"Carta de Proudhon a Marx (Lyon, 17 de mayo de 1846)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-beefs","hf-marx-biblioteca"]},"balmes":{"name":"Jaime Balmes","dates":"1810 – 1848","born":1810,"died":1848,"place":"Vic (Barcelona, Cataluña)","role":"sacerdote, filósofo y escritor político","idea":"Pensar bien es ver la verdad de las cosas y distinguir lo verdadero de lo falso; la fe y la razón no se oponen, sino que se necesitan.","obras":["El criterio (1845)","Filosofía fundamental (1846)","El protestantismo comparado con el catolicismo en sus relaciones con la civilización europea (1842-1844)","Filosofía elemental (1847)"],"fuente":"J. Balmes, El protestantismo comparado con el catolicismo (1842-1844); F. Guizot, Historia de la civilización en Europa (1828); biografías de referencia (Real Academia de la Historia, «Jaime Balmes»)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-filosofia-espanola"]},"dickens":{"name":"Charles Dickens","dates":"1812 – 1870","born":1812,"died":1870,"place":"Portsmouth (Inglaterra)","role":"novelista y periodista","idea":"Una sociedad que solo cuenta datos, beneficios y utilidad olvida a las personas, sobre todo a los niños y a los pobres.","obras":["Oliver Twist (1837-1839)","Cuento de Navidad (1843)","David Copperfield (1849-1850)","Tiempos difíciles (1854)"],"fuente":"Fragmento autobiográfico de Dickens recogido por John Forster en La vida de Charles Dickens (1872-1874)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-kant-poetas","hf-corazon-piedra"]},"buchner":{"name":"Georg Büchner","dates":"1813 – 1837","born":1813,"died":1837,"place":"Goddelau (Alemania)","role":"dramaturgo, médico y revolucionario","idea":"La naturaleza no actúa según fines: todo lo que existe está ahí por sí mismo, y la ciencia debe buscar sus leyes en lugar de preguntar para qué sirve.","obras":["La muerte de Danton (1835)","Lenz (1835-1836)","Leonce y Lena (1836)","Woyzeck (1836-1837)"],"fuente":"Orden de busca y captura firmada por el juez Georgi (Darmstadt, 13 de junio de 1835), publicada en la Großherzoglich Hessische Zeitung (18 de junio de 1835); Georg Büchner Portal","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-kant-poetas","hf-corazon-piedra"]},"kierkegaard":{"name":"Søren Kierkegaard","dates":"1813 – 1855","born":1813,"died":1855,"place":"Copenhague (Dinamarca)","role":"filósofo y teólogo danés, precursor del existencialismo","idea":"La verdad que importa no es la de los sistemas, sino la que uno vive: cada individuo tiene que elegirse a sí mismo, y esa elección se hace con angustia.","obras":["O lo uno o lo otro (1843)","Temor y temblor (1843)","El concepto de la angustia (1844)","La enfermedad mortal (1849)"],"fuente":"El Corsario (1846); Diarios de Kierkegaard","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-existencialismo"]},"boole":{"name":"George Boole","dates":"1815 – 1864","born":1815,"died":1864,"place":"Lincoln (Inglaterra)","role":"matemático y lógico británico","idea":"La lógica puede tratarse como un álgebra: con 1 para lo verdadero y 0 para lo falso, las conectivas se convierten en operaciones de cálculo.","obras":["El análisis matemático de la lógica (1847)","Las leyes del pensamiento (1854)"],"fuente":"Desmond MacHale, George Boole: His Life and Work","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-kant-juicios"]},"marx":{"name":"Karl Marx","dates":"1818 – 1883","born":1818,"died":1883,"place":"Tréveris (Prusia)","role":"filósofo, economista y revolucionario","idea":"La estructura económica determina la sociedad y sus ideas; bajo el capitalismo el trabajador está alienado y explotado, y solo una revolución puede crear una sociedad sin clases.","obras":["Manuscritos económico-filosóficos (1844)","Tesis sobre Feuerbach (1845)","Manifiesto comunista (1848)","El capital (1867)"],"fuente":"Carta de Engels a Eduard Bernstein (1882)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-metodos","hf-beefs","hf-utopias-autoras","hf-metafisica","hf-spinoza-universal","hf-ilustracion","hf-kant-poetas","hf-etica-deber","hf-sospecha","hf-marx-biblioteca","hf-marxismos","hf-corazon-piedra","hf-capitalismo"]},"mendel":{"name":"Gregor Mendel","dates":"1822 – 1884","born":1822,"died":1884,"place":"Heinzendorf (Silesia, hoy República Checa)","role":"fraile agustino y naturalista","idea":"Los rasgos hereditarios se transmiten mediante unidades separadas, hoy llamadas genes, que se combinan de generación en generación siguiendo proporciones regulares y previsibles.","obras":["Experimentos sobre hibridación de plantas (1866)"],"fuente":"Correspondencia de Mendel con Carl von Nägeli","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marxismos"]},"kropotkin":{"name":"Piotr Kropotkin","dates":"1842 – 1921","born":1842,"died":1921,"place":"Moscú","role":"geógrafo y pensador anarquista","idea":"El apoyo mutuo es un factor de la evolución tan importante como la lucha: las especies que cooperan prosperan, y en ese instinto social se basa la moral.","obras":["La conquista del pan (1892)","Campos, fábricas y talleres (1899)","El apoyo mutuo (1902)"],"fuente":"Piotr Kropotkin, Memorias de un revolucionario","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-utilitarismo"]},"nietzsche":{"name":"Friedrich Nietzsche","dates":"1844 – 1900","born":1844,"died":1900,"place":"Röcken (Sajonia, Prusia)","role":"filósofo y filólogo alemán","idea":"Tras la muerte de Dios y la caída de los valores tradicionales, el ser humano debe superar el nihilismo afirmando la vida y creando sus propios valores.","obras":["El nacimiento de la tragedia (1872)","La gaya ciencia (1882)","Así habló Zaratustra (1883-1885)","La genealogía de la moral (1887)"],"fuente":"Carta de Nietzsche a Heinrich Köselitz (febrero de 1882)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-euskal-herria","hf-metodos","hf-beefs","hf-platon-superficie","hf-platon-agustin","hf-montaigne-ensayos","hf-spinoza-sistema","hf-spinoza-universal","hf-ilustracion","hf-kant-poetas","hf-etica-deber","hf-sospecha","hf-filosofas-dialogo","hf-posmodernidad","hf-existencialismo"]},"frege":{"name":"Gottlob Frege","dates":"1848 – 1925","born":1848,"died":1925,"place":"Wismar (Mecklemburgo)","role":"matemático, lógico y filósofo","idea":"Con un lenguaje formal de símbolos, la lógica puede eliminar las ambigüedades del lenguaje corriente y servir de fundamento a toda la aritmética.","obras":["Conceptografía (1879)","Los fundamentos de la aritmética (1884)","Sobre sentido y referencia (1892)","Leyes fundamentales de la aritmética (1893-1903)"],"fuente":"Testimonio de Wittgenstein recogido por Peter Geach; prólogo del Tractatus logico-philosophicus","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-kant-juicios"]},"freud":{"name":"Sigmund Freud","dates":"1856 – 1939","born":1856,"died":1939,"place":"Freiberg (Moravia, hoy República Checa)","role":"médico neurólogo, creador del psicoanálisis","idea":"La mayor parte de la vida psíquica es inconsciente: deseos reprimidos que no controlamos gobiernan lo que pensamos y hacemos, y su represión produce neurosis.","obras":["La interpretación de los sueños (1900)","Tres ensayos sobre teoría sexual (1905)","El yo y el ello (1923)","El malestar en la cultura (1930)"],"fuente":"Ernest Jones, Vida y obra de Sigmund Freud","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-ilustracion","hf-sospecha","hf-filosofas-dialogo","hf-capitalismo","hf-posmodernidad"]},"zetkin":{"name":"Clara Zetkin","dates":"1857 – 1933","born":1857,"died":1933,"place":"Wiederau (Sajonia, Alemania)","role":"política, periodista y teórica socialista alemana","idea":"Unió la emancipación de las mujeres y la lucha de clases: sin independencia económica y sin cambiar la sociedad capitalista, la igualdad ante la ley se queda a medias.","obras":["La cuestión de las obreras y de las mujeres en el presente (1889)","Die Gleichheit («La igualdad»), revista que dirigió de 1892 a 1917","Recuerdos sobre Lenin (escrito en 1924)"],"fuente":"Verhandlungen des Reichstags, VI. Wahlperiode 1932, Stenographische Berichte, 1.ª sesión, 30 de agosto de 1932 (actas taquigráficas del Reichstag)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-capitalismo"]},"bergson":{"name":"Henri Bergson","dates":"1859 – 1941","born":1859,"died":1941,"place":"París (Francia)","role":"filósofo francés de la duración y de la vida","idea":"El tiempo vivido, la duración, no se puede medir como el de los relojes: solo la intuición capta lo que cambia y fluye, y la vida es un impulso creador.","obras":["Ensayo sobre los datos inmediatos de la conciencia (1889)","Materia y memoria (1896)","La risa (1900)","La evolución creadora (1907)","Las dos fuentes de la moral y de la religión (1932)"],"fuente":"Boletín de la Sociedad Francesa de Filosofía (1922)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-spinoza-universal"]},"husserl":{"name":"Edmund Husserl","dates":"1859 – 1938","born":1859,"died":1938,"place":"Prossnitz (Moravia, hoy Prostějov, República Checa)","role":"filósofo alemán, fundador de la fenomenología","idea":"Hay que «volver a las cosas mismas»: describir sin prejuicios cómo aparecen las cosas en la conciencia, que siempre es conciencia de algo.","obras":["Investigaciones lógicas (1900-1901)","Ideas relativas a una fenomenología pura (1913)","Meditaciones cartesianas (1931)","La crisis de las ciencias europeas y la fenomenología trascendental (1936)"],"fuente":"H. L. Van Breda, «El salvamento del legado husserliano» (1959)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-existencialismo"]},"dewey":{"name":"John Dewey","dates":"1859 – 1952","born":1859,"died":1952,"place":"Burlington (Estados Unidos)","role":"filósofo pragmatista y reformador de la educación estadounidense","idea":"Pensar es investigar para resolver los problemas que plantea la experiencia; por eso la educación no consiste en memorizar, sino en «aprender haciendo», y la democracia es sobre todo una forma de vida compartida.","obras":["La escuela y la sociedad (1899)","Cómo pensamos (1910)","Democracia y educación (1916)","El arte como experiencia (1934)"],"fuente":"K. C. Mayhew y A. C. Edwards, The Dewey School (1936)","tradicion":false,"block":"con","subjects":["hf"],"temas":[]},"salome":{"name":"Lou Andreas-Salomé","dates":"1861 – 1937","born":1861,"died":1937,"place":"San Petersburgo","role":"escritora y psicoanalista","idea":"Pensó la religiosidad sin Dios, el erotismo y la creación artística; interlocutora de Nietzsche, Rilke y Freud, hizo de su propia libertad una forma de pensamiento.","obras":["Friedrich Nietzsche en sus obras","El erotismo","Mi vida (memorias)"],"fuente":"Lou Andreas-Salomé, *Friedrich Nietzsche en sus obras* y *Mi vida*; adaptado de Lola Cabrera Trigo, *El pensamiento en femenino plural* (Erein, serie «En diálogo con…»; CC BY-NC-SA 4.0)","tradicion":true,"block":"con","subjects":["hf"],"temas":["hf-filosofas-dialogo"]},"unamuno":{"name":"Miguel de Unamuno","dates":"1864 – 1936","born":1864,"died":1936,"place":"Bilbao","role":"filósofo, novelista y poeta","idea":"El ser humano de carne y hueso vive en agonía, en lucha permanente entre la razón, que niega la inmortalidad, y el corazón, que la anhela.","obras":["Del sentimiento trágico de la vida (1913)","Niebla (1914)","La agonía del cristianismo (1925)","San Manuel Bueno, mártir (1931)"],"fuente":"Unamuno, Amor y pedagogía (1902), «Apuntes para un tratado de cocotología»","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-euskal-herria","hf-filosofia-espanola","hf-existencialismo"]},"weber":{"name":"Max Weber","dates":"1864 – 1920","born":1864,"died":1920,"place":"Erfurt (Alemania)","role":"sociólogo, economista y filósofo alemán","idea":"El Estado moderno se apoya en una legitimidad legal y racional, y la acción política debe combinar la ética de la convicción con la ética de la responsabilidad.","obras":["La ética protestante y el espíritu del capitalismo (1905)","La ciencia como vocación (1919)","La política como vocación (1919)","Economía y sociedad (1922)"],"fuente":"Weber, La política como vocación (conferencia de 1919); Marianne Weber, biografía de Max Weber","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-etica-deber","hf-marxismos"]},"luxemburgo":{"name":"Rosa Luxemburgo","dates":"1871 – 1919","born":1871,"died":1919,"place":"Zamość (Polonia)","role":"pensadora y revolucionaria marxista","idea":"El socialismo y la democracia son inseparables: criticó tanto el reformismo que renuncia a transformar la sociedad como el poder de un solo partido, y confió en la iniciativa espontánea de los trabajadores.","obras":["¿Reforma social o revolución? (1899)","Huelga de masas, partido y sindicatos (1906)","La acumulación del capital (1913)","La revolución rusa (escrita en 1918)"],"fuente":"Rosa Luxemburgo, carta a Sofía Liebknecht desde la prisión de Breslau (mediados de diciembre de 1917), recogida en sus Cartas desde la prisión","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marxismos","hf-capitalismo"]},"russell":{"name":"Bertrand Russell","dates":"1872 – 1970","born":1872,"died":1970,"place":"Trellech (Gales)","role":"filósofo, lógico y matemático británico","idea":"El análisis lógico del lenguaje permite aclarar los problemas filosóficos, y la matemática puede fundarse en la lógica; defendió un lenguaje lógicamente perfecto que refleje la estructura del mundo.","obras":["Principia Mathematica (1910-1913, con Whitehead)","Los problemas de la filosofía (1912)","Historia de la filosofía occidental (1945)"],"fuente":"Correspondencia entre Russell y Frege (1902); Frege, apéndice al vol. II de Las leyes fundamentales de la aritmética","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-mito","hf-cinco-vias","hf-analitica"]},"kollontai":{"name":"Aleksandra Kollontái","dates":"1872 – 1952","born":1872,"died":1952,"place":"San Petersburgo (Imperio ruso)","role":"revolucionaria y diplomática soviética","idea":"Unió el socialismo y la emancipación de la mujer: la igualdad legal no basta si no cambian el trabajo doméstico, la familia y las relaciones amorosas.","obras":["Las bases sociales de la cuestión femenina (1909)","La nueva moral y la clase obrera (1918)","La oposición obrera (1921)","¡Abrid paso al Eros alado! (1923)"],"fuente":"Cathy Porter, Alexandra Kollontai. A Biography (Virago, 1980)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marxismos"]},"moore":{"name":"George Edward Moore","dates":"1873 – 1958","born":1873,"died":1958,"place":"Londres (Inglaterra)","role":"filósofo británico","idea":"La filosofía debe partir del sentido común y aclarar con precisión el significado de lo que decimos; el bien es una cualidad simple que no puede definirse.","obras":["Principia Ethica (1903)","La refutación del idealismo (1903)","Defensa del sentido común (1925)"],"fuente":"Moore, «Prueba del mundo exterior» (1939)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-racionalismo","hf-analitica"]},"einstein":{"name":"Albert Einstein","dates":"1879 – 1955","born":1879,"died":1955,"place":"Ulm (Alemania)","role":"físico teórico","idea":"Con la teoría de la relatividad mostró que el espacio y el tiempo no son absolutos, sino que dependen del observador y de la presencia de materia y energía.","obras":["Teoría de la relatividad especial (1905)","Teoría de la relatividad general (1915)"],"fuente":"Einstein, Notas autobiográficas (1949)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-beefs","hf-spinoza-sistema","hf-spinoza-universal","hf-kant-poetas"]},"maeztu":{"name":"María de Maeztu","dates":"1881 – 1948","born":1881,"died":1948,"place":"Vitoria-Gasteiz","role":"pedagoga","idea":"Llevó a la práctica la igualdad educativa de las mujeres: desde la Residencia de Señoritas abrió a las jóvenes el acceso a la universidad y a la vida intelectual de la España de su tiempo.","obras":[],"fuente":"Adaptado de Lola Cabrera Trigo, *El pensamiento en femenino plural* (Erein, serie «En diálogo con…»; CC BY-NC-SA 4.0); fechas según Diccionario biográfico Auñamendi (Eusko Ikaskuntza) y EcuRed (murió el 7-1-1948 en Mar del Plata; el libro da erróneamente 1952)","tradicion":true,"block":"con","subjects":["hf"],"temas":["hf-euskal-herria","hf-filosofia-espanola","hf-filosofas-dialogo"]},"schlick":{"name":"Moritz Schlick","dates":"1882 – 1936","born":1882,"died":1936,"place":"Berlín (Alemania)","role":"filósofo y físico alemán","idea":"El significado de una proposición es su método de verificación: lo que no puede comprobarse empíricamente ni es una verdad lógica carece de sentido.","obras":["Teoría general del conocimiento (1918)","Problemas de ética (1930)"],"block":"con","subjects":["hf"],"temas":["hf-analitica"]},"ortega":{"name":"José Ortega y Gasset","dates":"1883 – 1955","born":1883,"died":1955,"place":"Madrid","role":"filósofo y ensayista español","idea":"La vida de cada persona es la realidad radical: el yo es inseparable de su circunstancia, y la verdad se alcanza sumando las distintas perspectivas.","obras":["Meditaciones del Quijote (1914)","El tema de nuestro tiempo (1923)","La rebelión de las masas (1930)"],"fuente":"Ortega y Gasset, «El error Berenguer» (El Sol, 1930) y «Un aldabonazo» (Crisol, 1931)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-euskal-herria","hf-filosofia-espanola","hf-existencialismo","hf-beauvoir"]},"jaspers":{"name":"Karl Jaspers","dates":"1883 – 1969","born":1883,"died":1969,"place":"Oldemburgo (Alemania)","role":"psiquiatra y filósofo existencialista alemán","idea":"En las situaciones límite (la muerte, el sufrimiento, la lucha, la culpa) la persona descubre su propia existencia y su libertad, y aprende a comunicarse de verdad con los demás.","obras":["Psicopatología general (1913)","Filosofía (1932)","La cuestión de la culpa (1946)","Origen y meta de la historia (1949)"],"fuente":"K. Jaspers, Autobiografía filosófica (1957); cartas con Hannah Arendt","tradicion":false,"block":"con","subjects":["hf"],"temas":[]},"sapir":{"name":"Edward Sapir","dates":"1884 – 1939","born":1884,"died":1939,"place":"Lauenburg (Pomerania, hoy Polonia)","role":"lingüista y antropólogo estadounidense","idea":"La lengua que hablamos no se limita a expresar el pensamiento, sino que influye en cómo percibimos y organizamos la realidad.","obras":["El lenguaje (1921)"],"fuente":"Testimonios de Alfred Kroeber y documentación del museo de antropología de la Universidad de California; Theodora Kroeber, Ishi en dos mundos","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-analitica"]},"wittgenstein":{"name":"Ludwig Wittgenstein","dates":"1889 – 1951","born":1889,"died":1951,"place":"Viena (Austria)","role":"filósofo austriaco del lenguaje","idea":"Los problemas filosóficos nacen de malentendidos del lenguaje; primero concibió las proposiciones como figuras de los hechos y después el significado como uso en juegos de lenguaje.","obras":["Tractatus logico-philosophicus (1921)","Investigaciones filosóficas (1953)"],"fuente":"Testimonios recogidos en la biografía de Ray Monk, Ludwig Wittgenstein. El deber de un genio","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-historicidad","hf-beefs","hf-montaigne-ensayos","hf-analitica"]},"heidegger":{"name":"Martin Heidegger","dates":"1889 – 1976","born":1889,"died":1976,"place":"Messkirch (Alemania)","role":"filósofo alemán","idea":"El ser humano, el Dasein, es un ser arrojado al mundo y abocado a la muerte, que solo vive con autenticidad cuando asume su finitud y su libertad.","obras":["Ser y tiempo (1927)","¿Qué es metafísica? (1929)","El origen de la obra de arte","Carta sobre el humanismo (1947)"],"fuente":"Heidegger, curso de Marburgo de 1924 (Conceptos fundamentales de la filosofía aristotélica); testimonios de sus alumnos, como Arendt","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-euskal-herria","hf-filosofia-espanola","hf-beefs","hf-posmodernidad","hf-existencialismo"]},"carnap":{"name":"Rudolf Carnap","dates":"1891 – 1970","born":1891,"died":1970,"place":"Ronsdorf (Alemania)","role":"filósofo y lógico alemán","idea":"Con el análisis lógico del lenguaje se muestra que los enunciados de la metafísica no son falsos, sino carentes de significado, porque no pueden verificarse.","obras":["La construcción lógica del mundo (1928)","La superación de la metafísica mediante el análisis lógico del lenguaje (1932)","Sintaxis lógica del lenguaje (1934)"],"fuente":"Carnap, «Autobiografía intelectual», en P. A. Schilpp (ed.), The Philosophy of Rudolf Carnap","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-analitica"]},"gramsci":{"name":"Antonio Gramsci","dates":"1891 – 1937","born":1891,"died":1937,"place":"Ales (Italia)","role":"pensador marxista y político italiano","idea":"Una clase no domina solo por la fuerza, sino por la hegemonía: el consentimiento que obtiene a través de la cultura (la escuela, la prensa, la religión). Por eso la política se juega también en el terreno de las ideas y del sentido común.","obras":["La cuestión meridional (1926)","Cartas desde la cárcel (escritas 1926-1937)","Cuadernos de la cárcel (escritos 1929-1935)"],"fuente":"Giuseppe Fiori, Vida de Antonio Gramsci (1966); actas del proceso de 1928","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-marxismos","hf-capitalismo"]},"benjamin":{"name":"Walter Benjamin","dates":"1892 – 1940","born":1892,"died":1940,"place":"Berlín","role":"filósofo y crítico alemán","idea":"La reproducción técnica de las imágenes destruye el aura de la obra de arte única, pero la acerca a las masas y le da una nueva función política.","obras":["El origen del drama barroco alemán (1928)","La obra de arte en la época de su reproductibilidad técnica (1936)","Sobre el concepto de historia (1940)","Libro de los pasajes"],"fuente":"Benjamin, Sobre el concepto de historia, tesis IX; testimonios de Gershom Scholem","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marxismos","hf-capitalismo"]},"horkheimer":{"name":"Max Horkheimer","dates":"1895 – 1973","born":1895,"died":1973,"place":"Stuttgart (Alemania)","role":"filósofo y sociólogo alemán","idea":"La razón ilustrada se ha degradado en razón instrumental, que calcula los medios más eficaces sin preguntarse por los fines, y se ha convertido así en instrumento de dominación.","obras":["Teoría tradicional y teoría crítica (1937)","Dialéctica de la Ilustración (1944, con Adorno)","Crítica de la razón instrumental (1947)"],"fuente":"Lukács, prólogo de 1962 a Teoría de la novela","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marxismos","hf-capitalismo"]},"whorf":{"name":"Benjamin Lee Whorf","dates":"1897 – 1941","born":1897,"died":1941,"place":"Winthrop (Massachusetts, EE. UU.)","role":"lingüista estadounidense","idea":"La gramática de cada lengua condiciona la manera en que sus hablantes perciben, clasifican y piensan la realidad: es la tesis del relativismo lingüístico.","obras":["Lenguaje, pensamiento y realidad (1956)"],"fuente":"Whorf, «La relación del pensamiento y el comportamiento habituales con el lenguaje» (1939)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-analitica"]},"marcuse":{"name":"Herbert Marcuse","dates":"1898 – 1979","born":1898,"died":1979,"place":"Berlín (Alemania)","role":"filósofo de la Escuela de Fráncfort","idea":"La sociedad industrial avanzada crea necesidades falsas y nos hace sentir libres mientras nos integra en el sistema, de modo que se pierde la capacidad de imaginar otra forma de vivir.","obras":["Razón y revolución (1941)","Eros y civilización (1955)","El hombre unidimensional (1964)","«La tolerancia represiva» (1965)"],"fuente":"Prensa de 1968; entrevistas a Marcuse","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-marxismos","hf-capitalismo"]},"ryle":{"name":"Gilbert Ryle","dates":"1900 – 1976","born":1900,"died":1976,"place":"Brighton (Inglaterra)","role":"filósofo analítico británico","idea":"El dualismo cartesiano es un error categorial: la mente no es un fantasma dentro de la máquina del cuerpo, sino un conjunto de capacidades y disposiciones para actuar.","obras":["El concepto de lo mental (1949)","Dilemas (1954)"],"block":"con","subjects":["hf"],"temas":["hf-descartes-makro"]},"gaos":{"name":"José Gaos","dates":"1900 – 1969","born":1900,"died":1969,"place":"Gijón (Asturias)","role":"filósofo y traductor del exilio español en México","idea":"Los exiliados españoles en América no eran simples «desterrados», sino «transterrados»: habían cambiado de tierra, pero seguían en una tierra propia por la lengua y la cultura compartidas.","obras":["De la filosofía","Confesiones profesionales (1958)","Historia de nuestra idea del mundo","traducción de «El ser y el tiempo», de Heidegger (1951)"],"fuente":"M. Heidegger, El ser y el tiempo, trad. de José Gaos, Fondo de Cultura Económica, México, 1951 (prólogo del traductor)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-filosofia-espanola"]},"popper":{"name":"Karl Popper","dates":"1902 – 1994","born":1902,"died":1994,"place":"Viena","role":"filósofo de la ciencia","idea":"Una teoría es científica si es falsable, es decir, si puede ser refutada por la experiencia; la ciencia, como la política, avanza corrigiendo sus errores.","obras":["La lógica de la investigación científica (1934)","La sociedad abierta y sus enemigos (1945)","La miseria del historicismo (1957)","Conjeturas y refutaciones (1963)"],"fuente":"Popper, Búsqueda sin término (autobiografía); testimonios de los asistentes a la sesión","tradicion":true,"block":"con","subjects":["hf"],"temas":["hf-beefs","hf-platon","hf-politica","hf-sospecha","hf-capitalismo","hf-analitica"]},"adorno":{"name":"Theodor W. Adorno","dates":"1903 – 1969","born":1903,"died":1969,"place":"Fráncfort del Meno (Alemania)","role":"filósofo, sociólogo y musicólogo","idea":"La industria cultural convierte la cultura en mercancía que adormece a las masas; solo el arte autónomo y difícil conserva su capacidad crítica frente a la sociedad.","obras":["Dialéctica de la Ilustración (1944, con Horkheimer)","Minima moralia (1951)","Dialéctica negativa (1966)","Teoría estética (1970)"],"fuente":"Thomas Mann, Los orígenes del Doktor Faustus (1949)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-montaigne-ensayos","hf-utopias-autoras","hf-marxismos","hf-capitalismo"]},"zambrano":{"name":"María Zambrano","dates":"1904 – 1991","born":1904,"died":1991,"place":"Vélez-Málaga (Málaga)","role":"filósofa y ensayista española","idea":"Frente a una razón fría que ignora sentimientos y sueños, propone una razón poética que una filosofía y poesía para comprender en profundidad la vida humana.","obras":["Filosofía y poesía (1939)","El hombre y lo divino (1955)","Persona y democracia (1958)","Claros del bosque (1977)"],"fuente":"Testimonios biográficos y correspondencia de María Zambrano","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-filosofia-espanola","hf-existencialismo"]},"sartre":{"name":"Jean-Paul Sartre","dates":"1905 – 1980","born":1905,"died":1980,"place":"París","role":"filósofo y escritor francés","idea":"No hay una naturaleza humana previa: la existencia precede a la esencia, y cada persona, condenada a ser libre, es plenamente responsable de lo que hace de sí misma.","obras":["La náusea (1938)","El ser y la nada (1943)","El existencialismo es un humanismo (1946)","Crítica de la razón dialéctica (1960)"],"fuente":"Simone de Beauvoir, La plenitud de la vida (La force de l'âge)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-beefs","hf-marxismos","hf-existencialismo","hf-beauvoir"]},"arendt":{"name":"Hannah Arendt","dates":"1906 – 1975","born":1906,"died":1975,"place":"Linden (Hannover, Alemania)","role":"filósofa y teórica política","idea":"El totalitarismo destruye la pluralidad y el espacio público; incluso el mal extremo puede surgir de personas corrientes que renuncian a pensar por sí mismas.","obras":["Los orígenes del totalitarismo (1951)","La condición humana (1958)","Eichmann en Jerusalén (1963)","Verdad y política (1967)"],"fuente":"Entrevista con Günter Gaus, «Zur Person» (ZDF, 1964)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-ilustracion","hf-capitalismo"]},"copleston":{"name":"Frederick Copleston","dates":"1907 – 1994","born":1907,"died":1994,"place":"Trull, cerca de Taunton (Inglaterra)","role":"sacerdote jesuita e historiador de la filosofía","idea":"Si todo lo que hay en el mundo podría no existir, el mundo no se explica por sí mismo: hace falta un ser que exista por sí mismo y sea la razón de que haya algo.","obras":["Historia de la filosofía (9 volúmenes, 1946-1975)","Aquinas (1955)","Debate con Bertrand Russell sobre la existencia de Dios (BBC, 1948)"],"fuente":"Transcripción del debate Russell-Copleston (BBC, 28 de enero de 1948), publicada en B. Russell, Por qué no soy cristiano (1957)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-cinco-vias"]},"beauvoir":{"name":"Simone de Beauvoir","dates":"1908 – 1986","born":1908,"died":1986,"place":"París","role":"filósofa y escritora francesa","idea":"La identidad femenina es una construcción cultural y no un destino biológico: la mujer ha sido definida como lo otro del hombre y debe conquistar su libertad.","obras":["Para una moral de la ambigüedad (1947)","El segundo sexo (1949)","Los mandarines (1954)","La vejez (1970)"],"fuente":"Simone de Beauvoir, Memorias de una joven formal (1958)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-ilustracion","hf-filosofas-dialogo","hf-beauvoir"]},"weil":{"name":"Simone Weil","dates":"1909 – 1943","born":1909,"died":1943,"place":"París (Francia)","role":"filósofa francesa","idea":"Antes que los derechos están las obligaciones hacia los demás; prestar verdadera atención a quien sufre es la forma más alta de justicia y de respeto a su dignidad.","obras":["Reflexiones sobre las causas de la libertad y de la opresión social (escrito en 1934; publicado en 1955)","La gravedad y la gracia (1947)","Echar raíces (1949)","A la espera de Dios (1950)"],"fuente":"Simone Pétrement, Vida de Simone Weil (1973); Simone Weil, La condición obrera (diario de fábrica, 1934-1935)","tradicion":false,"block":"con","subjects":["hf"],"temas":[]},"turing":{"name":"Alan Turing","dates":"1912 – 1954","born":1912,"died":1954,"place":"Londres","role":"matemático y pionero informático","idea":"Si una máquina puede conversar de modo que no la distingamos de un ser humano, tenemos motivos para decir que piensa: es la idea del test de Turing.","obras":["Sobre los números computables (1936)","Maquinaria computacional e inteligencia (1950)"],"fuente":"Andrew Hodges, Alan Turing: The Enigma; prensa local de 1926","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-metafisica","hf-descartes-makro"]},"camus":{"name":"Albert Camus","dates":"1913 – 1960","born":1913,"died":1960,"place":"Mondovi (Argelia)","role":"escritor y filósofo francés","idea":"La vida es absurda porque el mundo no responde a nuestra exigencia de sentido; la respuesta no es huir de ella, sino vivirla con lucidez y rebeldía.","obras":["El extranjero (1942)","El mito de Sísifo (1942)","La peste (1947)","El hombre rebelde (1951)"],"fuente":"Texto de Camus para el boletín del Racing Universitaire d'Alger (años cincuenta); testimonios biográficos","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-beefs","hf-existencialismo"]},"ricoeur":{"name":"Paul Ricoeur","dates":"1913 – 2005","born":1913,"died":2005,"place":"Valence (Francia)","role":"filósofo francés, hermeneuta","idea":"Comprender al ser humano exige interpretar sus símbolos, textos y relatos, porque solo nos conocemos a nosotros mismos a través del rodeo de la interpretación.","obras":["Freud: una interpretación de la cultura (1965)","La metáfora viva (1975)","Tiempo y narración (1983-1985)","Sí mismo como otro (1990)"],"fuente":"Ricoeur, Autobiografía intelectual (Réflexion faite)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-sospecha"]},"rawls":{"name":"John Rawls","dates":"1921 – 2002","born":1921,"died":2002,"place":"Baltimore (Estados Unidos)","role":"filósofo político estadounidense","idea":"Una sociedad justa es la que elegiríamos tras un velo de ignorancia: con iguales libertades básicas y desigualdades admitidas solo si benefician a los peor situados.","obras":["Teoría de la justicia (1971)","Liberalismo político (1993)","El derecho de gentes (1999)","La justicia como equidad: una reformulación (2001)"],"fuente":"Thomas Pogge, John Rawls: su vida y su teoría de la justicia; J. Rawls, «Fifty Years after Hiroshima», Dissent (1995)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-historicidad","hf-capitalismo","hf-beauvoir"]},"kuhn":{"name":"Thomas Kuhn","dates":"1922 – 1996","born":1922,"died":1996,"place":"Cincinnati (Estados Unidos)","role":"filósofo de la ciencia","idea":"La ciencia no avanza solo acumulando verdades: alterna largos periodos de ciencia normal dentro de un paradigma con revoluciones científicas que lo sustituyen por otro.","obras":["La revolución copernicana (1957)","La estructura de las revoluciones científicas (1962)","La tensión esencial (1977)"],"fuente":"Primera edición de La estructura de las revoluciones científicas (International Encyclopedia of Unified Science, 1962); cartas de Carnap a Kuhn estudiadas por G. Reisch","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-analitica"]},"lyotard":{"name":"Jean-François Lyotard","dates":"1924 – 1998","born":1924,"died":1998,"place":"Versalles (Francia)","role":"filósofo francés de la posmodernidad","idea":"La posmodernidad es la incredulidad hacia los metarrelatos: ya no creemos en grandes narraciones que den sentido a toda la historia, sino en pequeños relatos plurales.","obras":["Discurso, figura (1971)","Economía libidinal (1974)","La condición posmoderna (1979)","La diferencia (1983)"],"fuente":"Exposición Les Immatériaux (Centro Pompidou, 1985) y su catálogo","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-beefs","hf-posmodernidad"]},"feyerabend":{"name":"Paul Feyerabend","dates":"1924 – 1994","born":1924,"died":1994,"place":"Viena (Austria)","role":"filósofo de la ciencia","idea":"No existe un único método científico válido para siempre; los grandes avances de la ciencia se lograron muchas veces rompiendo las reglas, por eso «todo vale».","obras":["Tratado contra el método (1975)","La ciencia en una sociedad libre (1978)","Adiós a la razón (1987)","Matando el tiempo (autobiografía, 1995)"],"fuente":"Paul Feyerabend, Matando el tiempo (autobiografía, 1995); el lema «todo vale» en Tratado contra el método (1975)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-analitica"]},"bauman":{"name":"Zygmunt Bauman","dates":"1925 – 2017","born":1925,"died":2017,"place":"Poznań (Polonia)","role":"sociólogo y filósofo polaco","idea":"Vivimos en una modernidad líquida, donde los vínculos, las instituciones y las identidades ya no son sólidos, sino precarios y cambiantes, y el ciudadano se vuelve consumidor.","obras":["Modernidad y Holocausto (1989)","Modernidad líquida (2000)","Amor líquido (2003)","Vidas desperdiciadas (2004)"],"block":"con","subjects":["hf"],"temas":["hf-siglo21"]},"deleuze":{"name":"Gilles Deleuze","dates":"1925 – 1995","born":1925,"died":1995,"place":"París (Francia)","role":"filósofo francés de la diferencia y del deseo","idea":"La filosofía no describe esencias eternas, sino que crea conceptos para pensar la diferencia y el cambio; y el deseo no es una carencia, sino una fuerza que produce vínculos y mundos.","obras":["Nietzsche y la filosofía (1962)","Diferencia y repetición (1968)","El anti-Edipo (1972, con Félix Guattari)","Mil mesetas (1980, con Félix Guattari)"],"fuente":"François Dosse, Gilles Deleuze y Félix Guattari. Biografía cruzada (2007)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-spinoza-sistema","hf-spinoza-universal","hf-kant-poetas","hf-posmodernidad"]},"foucault":{"name":"Michel Foucault","dates":"1926 – 1984","born":1926,"died":1984,"place":"Poitiers (Francia)","role":"filósofo e historiador francés","idea":"El sujeto no es algo natural, sino una construcción de discursos y relaciones de poder; todo saber produce poder, y el poder produce formas de saber.","obras":["Historia de la locura en la época clásica (1961)","Las palabras y las cosas (1966)","Vigilar y castigar (1975)","Historia de la sexualidad (1976-1984)"],"fuente":"Debate televisado Chomsky-Foucault (Eindhoven, 1971), publicado como La naturaleza humana: justicia versus poder","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-beefs","hf-posmodernidad","hf-beauvoir"]},"habermas":{"name":"Jürgen Habermas","dates":"1929 – 2026","born":1929,"died":2026,"place":"Düsseldorf (Alemania)","role":"filósofo y sociólogo alemán","idea":"La razón no debe abandonarse, sino hacerse dialógica: las normas y verdades se legitiman por el consenso alcanzado en un diálogo libre, igual y sin coacción.","obras":["Historia y crítica de la opinión pública (1962)","Conocimiento e interés (1968)","Teoría de la acción comunicativa (1981)","El discurso filosófico de la modernidad (1985)"],"fuente":"J. Habermas, «Pensar con Heidegger contra Heidegger», Frankfurter Allgemeine Zeitung (1953)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-beefs","hf-marxismos","hf-capitalismo","hf-posmodernidad"]},"wilson":{"name":"Edward O. Wilson","dates":"1929 – 2021","born":1929,"died":2021,"place":"Birmingham (Alabama, Estados Unidos)","role":"biólogo y naturalista","idea":"La conducta social tiene bases biológicas, y el éxito evolutivo de especies como la humana se explica en buena parte por la cooperación dentro de los grupos.","obras":["Sociobiología (1975)","Sobre la naturaleza humana (1978)","Las hormigas (1990, con B. Hölldobler)","La conquista social de la Tierra (2012)"],"fuente":"E. O. Wilson, El naturalista (autobiografía, 1994)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-utilitarismo"]},"txillardegi":{"name":"Txillardegi","dates":"1929 – 2012","born":1929,"died":2012,"place":"San Sebastián (Guipúzcoa)","role":"lingüista, escritor y político vasco","idea":"No pensamos antes de hablar, sino gracias a una lengua que estructura nuestra visión del mundo; por eso el euskera es la columna vertebral de la identidad vasca.","obras":["Leturiaren egunkari ezkutua (1957)","Huntaz eta hartaz (1965)","Hizkuntza eta pentsakera (1983)"],"block":"con","subjects":["hf"],"temas":["hf-euskal-herria","hf-analitica"]},"baudrillard":{"name":"Jean Baudrillard","dates":"1929 – 2007","born":1929,"died":2007,"place":"Reims (Francia)","role":"sociólogo y filósofo francés","idea":"Vivimos en la hiperrealidad: los simulacros, copias sin original, ya no representan la realidad, sino que la sustituyen y parecen más reales que ella.","obras":["El sistema de los objetos (1968)","La sociedad de consumo (1970)","Cultura y simulacro (1981)","La guerra del Golfo no ha tenido lugar (1991)"],"fuente":"Película Matrix (1999); entrevista a Baudrillard en Le Nouvel Observateur (2004)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-posmodernidad"]},"heller":{"name":"Ágnes Heller","dates":"1929 – 2019","born":1929,"died":2019,"place":"Budapest","role":"filósofa","idea":"Desde un marxismo renovado pensó la vida cotidiana como base de lo social y las «necesidades radicales» como motor del cambio; después defendió la democracia frente a la «dictadura de las necesidades» del socialismo real.","obras":["La teoría de las necesidades en Marx","Sociología de la vida cotidiana","Una filosofía de la historia en fragmentos"],"fuente":"Ágnes Heller, *La teoría de las necesidades en Marx* y *Sociología de la vida cotidiana*; adaptado de Lola Cabrera Trigo, *El pensamiento en femenino plural* (Erein, serie «En diálogo con…»; CC BY-NC-SA 4.0)","tradicion":true,"block":"con","subjects":["hf"],"temas":["hf-filosofas-dialogo"]},"derrida":{"name":"Jacques Derrida","dates":"1930 – 2004","born":1930,"died":2004,"place":"El Biar (Argelia)","role":"filósofo francés","idea":"La deconstrucción muestra que los conceptos de la filosofía se apoyan en oposiciones jerárquicas ocultas y que ningún significado escapa por completo al juego del lenguaje.","obras":["De la gramatología (1967)","La escritura y la diferencia (1967)","Márgenes de la filosofía (1972)","Espectros de Marx (1993)"],"fuente":"Benoît Peeters, Derrida (biografía, 2010); prensa de la época","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-posmodernidad"]},"rorty":{"name":"Richard Rorty","dates":"1931 – 2007","born":1931,"died":2007,"place":"Nueva York (Estados Unidos)","role":"filósofo estadounidense, representante del neopragmatismo","idea":"No hay una verdad que sea copia exacta de la realidad ni un fundamento último del saber; en una democracia conviene cambiar la búsqueda de la Verdad por la conversación, la ironía y la solidaridad.","obras":["La filosofía y el espejo de la naturaleza (1979)","Consecuencias del pragmatismo (1982)","Contingencia, ironía y solidaridad (1989)","Forjar nuestro país (1998)"],"fuente":"Richard Rorty, «Trotski y las orquídeas silvestres» (1992), recogido en Filosofía y futuro (ed. cast. Gedisa, 2002)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-posmodernidad"]},"vattimo":{"name":"Gianni Vattimo","dates":"1936 – 2023","born":1936,"died":2023,"place":"Turín (Italia)","role":"filósofo italiano","idea":"El pensamiento débil renuncia a las verdades absolutas y a los fundamentos últimos, y acepta la pluralidad de interpretaciones como base de una ética de la tolerancia.","obras":["El pensamiento débil (1983, con Pier Aldo Rovatti)","El fin de la modernidad (1985)","La sociedad transparente (1989)","Creer que se cree (1996)"],"block":"con","subjects":["hf"],"temas":["hf-posmodernidad"]},"azurmendi":{"name":"Joxe Azurmendi","dates":"1941 – 2025","born":1941,"died":2025,"place":"Zegama (Gipuzkoa)","role":"filósofo y ensayista vasco","idea":"Los valores dependen del contexto histórico y cultural, pero eso no los vuelve arbitrarios: su relativismo relativo rechaza los absolutos sin caer en el nihilismo.","obras":["Gizona abere hutsa da (1975)","Espainolak eta euskaldunak (1992)","Humboldt: hizkuntza eta pentsamendua (2007)","Historia, arraza, nazioa (2014)"],"block":"con","subjects":["hf"],"temas":["hf-euskal-herria","hf-utilitarismo","hf-etica-deber","hf-analitica"]},"ingham":{"name":"Geoffrey Ingham","dates":"n. 1942","born":1942,"died":null,"place":"","role":"sociólogo y economista político británico","idea":"El dinero no es una simple mercancía, sino una promesa de pago creada socialmente, sobre todo como crédito bancario, y es un pilar del capitalismo.","obras":["The Nature of Money (2004)","Capitalism (2008)"],"block":"con","subjects":["hf"],"temas":["hf-utilitarismo"]},"nussbaum":{"name":"Martha Nussbaum","dates":"n. 1947","born":1947,"died":null,"place":"Nueva York (EE. UU.)","role":"filósofa estadounidense","idea":"La justicia no se mide por la riqueza de un país, sino por las capacidades reales que cada persona tiene para llevar una vida digna.","obras":["La fragilidad del bien (1986)","Las mujeres y el desarrollo humano (2000)","Sin fines de lucro (2010)","Crear capacidades (2011)"],"fuente":"Perfil de R. Aviv en The New Yorker (2016) y entrevistas","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-beauvoir","hf-siglo21"]},"butler":{"name":"Judith Butler","dates":"n. 1956","born":1956,"died":null,"place":"Cleveland (Ohio, EE. UU.)","role":"referente de la teoría queer","idea":"El género no es una esencia biológica, sino una performance: se produce al repetir gestos y normas, y por eso puede transformarse y subvertirse.","obras":["El género en disputa (1990)","Cuerpos que importan (1993)","Vida precaria (2004)","La fuerza de la no violencia (2020)"],"fuente":"Testimonio de Judith Butler en entrevistas","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-beauvoir","hf-siglo21"]},"han":{"name":"Byung-Chul Han","dates":"n. 1959","born":1959,"died":null,"place":"Seúl (Corea del Sur)","role":"filósofo surcoreano-alemán","idea":"En la sociedad del rendimiento ya no nos explota un amo exterior: nos autoexplotamos creyéndonos libres, y el resultado es el cansancio y la depresión.","obras":["La sociedad del cansancio (2010)","La sociedad de la transparencia (2012)","Psicopolítica (2014)","La expulsión de lo distinto (2016)"],"fuente":"Byung-Chul Han, Loa a la tierra. Un viaje al jardín (2018)","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-platon-superficie","hf-siglo21"]},"herrero":{"name":"Yayo Herrero","dates":"n. 1965","born":1965,"died":null,"place":"Madrid","role":"antropóloga y activista ecofeminista","idea":"Los seres humanos somos ecodependientes e interdependientes, así que la economía y la política deben poner en el centro la vida y los cuidados.","obras":["Los cinco elementos (2021)","Ausencias y extravíos (2021)","Toma de tierra (2023)"],"block":"con","subjects":["hf"],"temas":["hf-siglo21"]},"chalmers":{"name":"David Chalmers","dates":"n. 1966","born":1966,"died":null,"place":"Sídney (Australia)","role":"filósofo de la mente australiano","idea":"Explicar las funciones del cerebro no basta para explicar la experiencia subjetiva: por qué sentimos algo es el problema difícil de la conciencia.","obras":["La mente consciente (1996)","Reality+ (2022)"],"fuente":"Crónicas del congreso de la Association for the Scientific Study of Consciousness (Nueva York, 2023), entre ellas la de Nature","tradicion":false,"block":"con","subjects":["hf"],"temas":["hf-descartes-simulacion","hf-descartes-makro"]},"klein":{"name":"Naomi Klein","dates":"n. 1970","born":1970,"died":null,"place":"Montreal (Canadá)","role":"periodista y ensayista canadiense","idea":"El capitalismo del desastre aprovecha el shock de las crisis, guerras y catástrofes para imponer reformas neoliberales que en tiempos normales serían rechazadas.","obras":["No Logo (2000)","La doctrina del shock (2007)","Esto lo cambia todo (2014)"],"block":"con","subjects":["hf"],"temas":["hf-siglo21"]},"preciado":{"name":"Paul B. Preciado","dates":"n. 1970","born":1970,"died":null,"place":"Burgos","role":"filósofo y comisario de arte","idea":"En la era farmacopornográfica el capitalismo gobierna los cuerpos mediante fármacos, hormonas e imágenes, pero el cuerpo puede convertirse en espacio de resistencia.","obras":["Manifiesto contrasexual (2000)","Testo yonqui (2008)","Un apartamento en Urano (2019)","Yo soy el monstruo que os habla (2020)"],"block":"con","subjects":["hf"],"temas":["hf-siglo21"]},"bostrom":{"name":"Nick Bostrom","dates":"n. 1973","born":1973,"died":null,"place":"Helsingborg (Suecia)","role":"filósofo sueco","idea":"Si las civilizaciones avanzadas pueden simular mundos con seres conscientes y deciden hacerlo, es probable que nosotros mismos vivamos en una simulación informática.","obras":["¿Vives en una simulación por ordenador? (2003)","Superinteligencia (2014)"],"block":"con","subjects":["hf"],"temas":["hf-descartes-simulacion","hf-descartes-makro"]}};
